const dataKuisKedkom2020=[{"id":"kedkom2020-1","soal":"Tn.Y istrinya meninggal karena melahirkan. Kematian itu masuk ke data mana?","opsi":["Angka kematian ibu","Angka kematian perempuan","Angka kematian maternal","Angka kematian wanita","Angka kematian bayi"],"jawabanBenar":2,"pembahasan":"Angka kematian maternal (maternal mortality) adalah kematian wanita selama hamil, bersalin, atau dalam 42 hari setelah berakhirnya kehamilan, terlepas dari durasi dan lokasi kehamilan, akibat semua hal yang terkait dengan atau diperparah oleh kehamilan atau penanganannya[cite: 1].","pembahasanPilihan":["Angka kematian ibu merupakan istilah umum yang sering disamakan, namun secara spesifik metrik kesehatan masyarakat menggunakan istilah angka kematian maternal.","Angka kematian perempuan mencakup seluruh penyebab kematian pada kelompok perempuan secara umum, bukan spesifik terkait proses kehamilan dan persalinan.","Angka kematian maternal (maternal mortality) adalah kematian wanita selama hamil, bersalin, atau dalam 42 hari setelah berakhirnya kehamilan, terlepas dari durasi dan lokasi kehamilan, akibat semua hal yang terkait dengan atau diperparah oleh kehamilan atau penanganannya[cite: 1].","Angka kematian wanita terlalu luas dan tidak spesifik mengukur risiko obstetrik.","Angka kematian bayi mengukur kematian anak pada usia di bawah 1 tahun, bukan kematian ibunya."],"version":1},{"id":"kedkom2020-2","soal":"SDGs merupakan penyempurnaan MDGs, SDGs secara spesifik menyasar pada kelompok rentan, termasuk apakah hal ini?","opsi":["No man left behind","No Poverty","Zero Hunger","Quality Education","Gender Equality"],"jawabanBenar":0,"pembahasan":"Prinsip utama Sustainable Development Goals (SDGs) adalah 'No One Left Behind' (tidak ada seorang pun yang tertinggal) untuk memastikan kelompok rentan turut merasakan pembangunan.","pembahasanPilihan":["Prinsip utama Sustainable Development Goals (SDGs) adalah 'No One Left Behind' (tidak ada seorang pun yang tertinggal) untuk memastikan kelompok rentan turut merasakan pembangunan.","No Poverty adalah tujuan (goal) pertama dari SDGs, bukan prinsip universal penyasar kelompok rentan secara keseluruhan.","Zero Hunger merupakan tujuan khusus kedua dalam pilar SDGs.","Quality Education merupakan tujuan keempat dalam pilar SDGs.","Gender Equality merupakan tujuan kelima dalam pilar SDGs."],"version":1},{"id":"kedkom2020-3","soal":"KLB DBD januari - maret, 10 meninggal dari 30 yg terkena DBD, april - desember 50 orang terkena DBD case fatality ratenya berapa?","opsi":["0,3","33,33","12,5","0,125","3,33"],"jawabanBenar":1,"pembahasan":"Case Fatality Rate (CFR) dihitung dari jumlah kematian akibat penyakit tertentu dibagi jumlah kasus penyakit tersebut dikali 100%. Berdasarkan data, terdapat 10 kematian dari 30 kasus pada periode awal (10/30 * 100% = 33,33%)[cite: 1].","pembahasanPilihan":["Nilai 0,3 merupakan hasil pembagian mentah sebelum dikalikan persentase 100%.","Case Fatality Rate (CFR) dihitung dari jumlah kematian akibat penyakit tertentu dibagi jumlah kasus penyakit tersebut dikali 100%. Berdasarkan data, terdapat 10 kematian dari 30 kasus pada periode awal (10/30 * 100% = 33,33%)[cite: 1].","12,5 merupakan angka yang salah perhitungan dari variabel soal.","0,125 merupakan bentuk desimal tanpa dikali persentase penuh.","3,33 adalah kesalahan penempatan desimal."],"version":1},{"id":"kedkom2020-4","soal":"Seorang anak laki-laki usia 2 tahun 1 bulan dengan BB 8.5 kg dan PB 70 cm datang dengan keluhan BAB mencret 1 bulan ini, tidak mau makan dan hanya minum ASI, belum bisa duduk sendiri dan belum bisa jalan, hanya dapat berbicara 'mama-papa'. Orang tua bekerja sebagai pemulung dengan 5 anak masih kecil. Apakah masalah kesehatan anak tersebut?","opsi":["Gizi buruk dengan keterlambatan perkembangan global","Gizi kurang dengan keterlambatan perkembangan global","Gizi buruk dengan keterlambatan motorik kasar","Gizi kurang dengan keterlambatan motorik kasar","Gizi buruk dengan serebral palsi"],"jawabanBenar":0,"pembahasan":"Berdasarkan antropometri (BB/PB < -3 SD), anak mengalami gizi buruk, disertai gangguan pada berbagai sektor perkembangan (motorik kasar, halus, bicara, sosialisasi) yang dikategorikan sebagai keterlambatan perkembangan global (global developmental delay)[cite: 1].","pembahasanPilihan":["Berdasarkan antropometri (BB/PB < -3 SD), anak mengalami gizi buruk, disertai gangguan pada berbagai sektor perkembangan (motorik kasar, halus, bicara, sosialisasi) yang dikategorikan sebagai keterlambatan perkembangan global (global developmental delay)[cite: 1].","Gizi kurang berada pada rentang -3 SD sampai < -2 SD, sedangkan kasus ini menunjukkan gizi buruk (< -3 SD).","Keterlambatan tidak hanya terbatas pada motorik kasar, melainkan mencakup aspek lain secara global.","Status gizi anak sudah masuk kategori gizi buruk, bukan gizi kurang.","Serebral palsi merupakan kelainan neuromuskular spesifik yang tidak dapat disimpulkan langsung hanya dari data keterlambatan nutrisi dan global ini tanpa pemeriksaan neurologis fokal."],"version":1},{"id":"kedkom2020-5","soal":"Untuk meningkatkan cakupan vaksinasi Covid-19, Klinik A melakukan vaksinasi massal namun klinik A ini tidak memiliki tempat untuk menyimpan vaksin, jadi klinik A melakukan kerjasama dengan pihak lain. Rujukan apakah yang dilakukan oleh klinik A ini?","opsi":["Rujukan Spesimen","Rujukan Tenaga","Rujukan Vertikal","Rujukan Kasus","Rujukan Sarana dan Logistik"],"jawabanBenar":4,"pembahasan":"Rujukan sarana dan logistik mencakup peminjaman atau penggunaan fasilitas, alat, atau bahan medis seperti tempat penyimpanan vaksin/cold chain[cite: 1].","pembahasanPilihan":["Rujukan spesimen berkaitan dengan pengiriman sampel biologis bahan pemeriksaan laboratorium[cite: 1].","Rujukan tenaga berkaitan dengan peminjaman atau pengiriman tenaga ahli medis.","Rujukan vertikal adalah rujukan antar strata fasilitas pelayanan kesehatan yang berbeda tingkatan.","Rujukan kasus berkaitan dengan perpindahan pasien untuk penanganan medis lebih lanjut.","Rujukan sarana dan logistik mencakup peminjaman atau penggunaan fasilitas, alat, atau bahan medis seperti tempat penyimpanan vaksin/cold chain[cite: 1]."],"version":1},{"id":"kedkom2020-6","soal":"Riskesdas 2010 menyatakan bahwa sekitar 49% rumah tangga di Indonesia menggunakan cara-cara pembuangan yang tidak aman. Penyebab kematian bayi dan balita adalah diare. Apakah penyebab utama masalah tersebut?","opsi":["Pemberian makan dan pelayanan lain yang buruk","Sanitasi yang buruk","Ibu kurang berpendidikan","Ibu dan kesehatan masyarakat kurang mengetahui penanggulangan penyakit umum anak","Faktor genetik lingkungan"],"jawabanBenar":1,"pembahasan":"Pembuangan kotoran dan limbah yang tidak aman secara langsung mencerminkan sanitasi yang buruk, yang menjadi pemicu utama penularan penyakit berbasis air (water-borne disease) seperti diare[cite: 1].","pembahasanPilihan":["Pemberian makan berkontribusi pada status gizi, namun rute penularan diare langsung berkaitan dengan higienitas lingkungan.","Pembuangan kotoran dan limbah yang tidak aman secara langsung mencerminkan sanitasi yang buruk, yang menjadi pemicu utama penularan penyakit berbasis air (water-borne disease) seperti diare[cite: 1].","Pendidikan ibu merupakan faktor tidak langsung dalam kerangka konseptual kesehatan.","Kurangnya pengetahuan adalah faktor perilaku pendukung, bukan akar lingkungan fisik utama.","Faktor genetik tidak berperan langsung dalam kejadian diare akibat sanitasi."],"version":1},{"id":"kedkom2020-7","soal":"Ny. C berusia 70 tahun berkonsultasi karena mau pergi haji selama 40 hari menggunakan pesawat selama 8 jam. Beliau post stroke dan menggunakan kursi roda. Beliau mengeluh kaki bengkak jika duduk terlalu lama. TD: 160/90 mmHg, suhu 36,5°C, frekuensi pernapasan: 18x/menit, nadi: 88x/menit. Karena negara yang dituju sangat panas, apa saran pencegahan yang tepat diberikan?","opsi":["Istirahat yang cukup","Makan 3 kali dengan porsi yang cukup","Membawa botol minum saat ibadah dan menggunakan penutup kepala","Meminum obat dan vitamin secara teratur","Menggunakan pakaian tebal berlapis"],"jawabanBenar":2,"pembahasan":"Mengingat kondisi cuaca di negara tujuan yang sangat panas serta risiko dehidrasi bagi lansia, membawa botol minum serta menggunakan penutup kepala/payung adalah antisipasi protektif yang esensial[cite: 1].","pembahasanPilihan":["Istirahat cukup bersifat umum dan tidak menjawab tantangan spesifik cuaca panas di tanah suci.","Nutrisi penting namun tidak mengantisipasi dehidrasi akibat suhu panas ekstrem.","Mengingat kondisi cuaca di negara tujuan yang sangat panas serta risiko dehidrasi bagi lansia, membawa botol minum serta menggunakan penutup kepala/payung adalah antisipasi protektif yang esensial[cite: 1].","Kepatuhan obat diperlukan untuk hipertensi, namun pencegahan lingkungan terhadap cuaca panas membutuhkan proteksi fisik langsung.","Pakaian tebal justru akan memperparah risiko heat stroke pada cuaca panas."],"version":1},{"id":"kedkom2020-8","soal":"Terjadi peningkatan kasus HIV sebanyak 50% dari tahun sebelumnya. Peningkatan ini tidak sejalan dengan peningkatan penggunaan ARV yang hanya 10%. Hal ini kemungkinan terjadi karena pasien HIV yang loss to follow up. Apa yang dilakukan puskesmas untuk mengurangi hambatan konseling kelompok?","opsi":["Melakukan layanan gratis","Melakukan penyuluhan berkala","Menyediakan loket khusus HIV","Membuat peer support (kelompok dukungan sebaya)","Memberikan ARV ke rumah ODHA"],"jawabanBenar":3,"pembahasan":"Pemberdayaan kelompok dukungan sebaya (peer support) terbukti efektif dalam mengurangi stigma, meningkatkan kepercayaan diri, dan menekan angka loss to follow up pada pasien HIV[cite: 1].","pembahasanPilihan":["Layanan gratis membantu finansial, namun hambatan psikososial konseling kelompok diatasi dengan kenyamanan emosional.","Penyuluhan bersifat satu arah, kurang efektif mengatasi keengganan kelompok dalam konseling interaktif.","Loket khusus membantu kerahasiaan administratif faskes, bukan hambatan interaksi kelompok.","Pemberdayaan kelompok dukungan sebaya (peer support) terbukti efektif dalam mengurangi stigma, meningkatkan kepercayaan diri, dan menekan angka loss to follow up pada pasien HIV[cite: 1].","Pengiriman ARV ke rumah adalah intervensi distribusi logistik, bukan solusi hambatan konseling kelompok."],"version":1},{"id":"kedkom2020-9","soal":"Dalam rangka menetapkan kasus kanker serviks, klinik A bekerjasama dengan laboratorium untuk dilakukan pemeriksaan histopatologis. Setelah sampel diambil, sampel dikirim ke laboratorium untuk dilakukan pemeriksaan oleh ahli patologi klinik. Disebut apakah rujukan tersebut?","opsi":["Rujukan Bahan Pemeriksaan (Rujukan Spesimen)","Rujukan Kasus","Rujukan Operasional","Rujukan Tugas","Rujukan Sarana dan Logistik"],"jawabanBenar":0,"pembahasan":"Pengiriman sampel biologis/jaringan tubuh pasien dari klinik ke fasilitas laboratorium rujukan untuk diperiksa dikategorikan sebagai rujukan bahan pemeriksaan atau rujukan spesimen[cite: 1].","pembahasanPilihan":["Pengiriman sampel biologis/jaringan tubuh pasien dari klinik ke fasilitas laboratorium rujukan untuk diperiksa dikategorikan sebagai rujukan bahan pemeriksaan atau rujukan spesimen[cite: 1].","Rujukan kasus melibatkan pemindahan pasien secara fisik untuk mendapatkan perawatan.","Rujukan operasional mencakup aspek manajerial, tenaga, atau administrasi penunjang.","Rujukan tugas tidak dikenal sebagai klasifikasi formal dalam sistem rujukan medis nasional.","Rujukan sarana dan logistik berkaitan dengan peminjaman alat atau fasilitas fisik."],"version":1},{"id":"kedkom2020-10","soal":"Indonesia memiliki angka perkawinan usia dini tertinggi di dunia. Sebanyak 1.220.900 perempuan berusia 20-24 tahun menikah sebelum usia 18 tahun. Kesimpulan apakah yang paling tepat ditarik dari fenomena tersebut?","opsi":["Permasalahan kesehatan reproduksi remaja (KRR) meningkat dan belum tersosialisasi optimal","Perlu badan khusus yang mengurusi logistik","Perjodohan usia dini harus diturunkan oleh pemerintah pusat","Pendidikan formal harus dihentikan pada usia sekolah dasar","Angka kematian bayi menurun drastis"],"jawabanBenar":0,"pembahasan":"Tingginya angka pernikahan anak mencerminkan rendahnya pemahaman serta belum optimalnya sosialisasi program Kesehatan Reproduksi Remaja (KRR) di masyarakat[cite: 1].","pembahasanPilihan":["Tingginya angka pernikahan anak mencerminkan rendahnya pemahaman serta belum optimalnya sosialisasi program Kesehatan Reproduksi Remaja (KRR) di masyarakat[cite: 1].","Pembentukan badan logistik tidak menjawab akar masalah sosial perkawinan anak.","Perjodohan hanyalah salah satu faktor kecil, bukan kesimpulan komprehensif atas seluruh data makro.","Menghentikan pendidikan justru memperburuk kerentanan anak terhadap pernikahan dini.","Pernikahan usia dini berkorelasi dengan peningkatan risiko kesehatan ibu dan anak, bukan menurunkan kematian bayi."],"version":1},{"id":"kedkom2020-11","soal":"Puskesmas diatur secara resmi dalam regulasi Kementerian Kesehatan melalui Peraturan Menteri Kesehatan Nomor berapa?","opsi":["Permenkes No. 43 Tahun 2016","Permenkes No. 75 Tahun 2014","Permenkes No. 43 Tahun 2019","Permenkes No. 23 Tahun 2014","Permenkes No. 2 Tahun 2020"],"jawabanBenar":2,"pembahasan":"Berdasarkan regulasi operasional terbaru yang berlaku umum, Puskesmas diatur dan disesuaikan ketentuannya melalui Permenkes No. 43 Tahun 2019 tentang Pusat Kesehatan Masyarakat[cite: 1].","pembahasanPilihan":["Permenkes 43 Tahun 2016 bukan regulasi utama yang mengatur organisasi Puskesmas.","Permenkes No. 75 Tahun 2014 adalah regulasi lama mengenai Pusat Kesehatan Masyarakat yang telah diperbarui.","Berdasarkan regulasi operasional terbaru yang berlaku umum, Puskesmas diatur dan disesuaikan ketentuannya melalui Permenkes No. 43 Tahun 2019 tentang Pusat Kesehatan Masyarakat[cite: 1].","Permenkes 23 Tahun 2014 tidak mengatur tentang Puskesmas.","Permenkes No. 2 Tahun 2020 mengatur hal lain di luar pedoman dasar Puskesmas."],"version":1},{"id":"kedkom2020-12","soal":"Pasien mengalami keputihan berbau tidak sedap selama 1 tahun. Termasuk ke dalam ruang lingkup masalah kesehatan apakah kondisi tersebut?","opsi":["Kesehatan anak","Kesehatan usia lanjut","Kesehatan reproduksi","Kesehatan jiwa","Kesehatan lingkungan"],"jawabanBenar":2,"pembahasan":"Keputihan berbau patologis yang berkaitan dengan organ intim dan infeksi saluran reproduksi termasuk ke dalam lingkup masalah kesehatan reproduksi[cite: 1].","pembahasanPilihan":["Kesehatan anak berfokus pada tumbuh kembang neonatus hingga remaja awal.","Kesehatan usia lanjut berfokus pada aspek geriatri.","Keputihan berbau patologis yang berkaitan dengan organ intim dan infeksi saluran reproduksi termasuk ke dalam lingkup masalah kesehatan reproduksi[cite: 1].","Kesehatan jiwa berfokus pada aspek psikologis dan psikiatris.","Kesehatan lingkungan berfokus pada faktor eksternal air, tanah, dan udara."],"version":1},{"id":"kedkom2020-13","soal":"Pada negara X terdapat kasus penyakit jantung sebanyak 250 pada tahun 2022, dengan jumlah penduduk sebanyak 5.000.000 jiwa. Berapakah insidens rate (angka kejadian) penyakit jantung di negara tersebut?","opsi":["0,25","0,025","250","0,005","0,05"],"jawabanBenar":3,"pembahasan":"Insidens rate dihitung dengan membagi jumlah kasus baru (250) dengan total populasi berisiko (5.000.000), menghasilkan 0,00005 atau setara dengan 0,005 per 100 penduduk (atau 0,005% jika dikalikan 100%)[cite: 1].","pembahasanPilihan":["0,25 merupakan hasil perhitungan yang salah.","0,025 adalah kesalahan faktor pengali desimal.","250 adalah jumlah absolut kasus mentah, bukan nilai rate.","Insidens rate dihitung dengan membagi jumlah kasus baru (250) dengan total populasi berisiko (5.000.000), menghasilkan 0,00005 atau setara dengan 0,005 per 100 penduduk (atau 0,005% jika dikalikan 100%)[cite: 1].","0,05 adalah hasil perkalian yang tidak akurat."],"version":1},{"id":"kedkom2020-14","soal":"Terjadi kasus kematian bayi dan sedang dilakukan audit maternal perinatal (AMP). Siapakah narasumber utama yang paling tepat untuk diwawancarai guna pengisian formulir otopsi verbal?","opsi":["Petugas Dinas Kesehatan","Keluarga pasien (orang tua/pengasuh)","Dokter kandungan di RS besar","Bidan RS rujukan","Kepala desa setempat"],"jawabanBenar":1,"pembahasan":"Otopsi verbal dilakukan dengan mewawancarai keluarga terdekat atau pengasuh yang mendampingi almarhum/almarhumah untuk mengetahui kronologis klinis sebelum meninggal[cite: 1].","pembahasanPilihan":["Petugas Dinas Kesehatan bertindak sebagai fasilitator atau pengawas audit, bukan saksi mata kejadian.","Otopsi verbal dilakukan dengan mewawancarai keluarga terdekat atau pengasuh yang mendampingi almarhum/almarhumah untuk mengetahui kronologis klinis sebelum meninggal[cite: 1].","Dokter spesialis di RS hanya mengetahui data saat pasien tiba di fasilitas rujukan akhir.","Bidan RS tidak mengetahui kondisi awal di rumah sebelum pasien dibawa berobat.","Kepala desa tidak memiliki kompetensi klinis kronologis medis."],"version":1},{"id":"kedkom2020-15","soal":"Pandemi Covid-19 telah berakhir dan masyarakat mulai menata kembali kehidupannya. Akan tetapi, suhu ekstrim menyebabkan banyak kebakaran hutan dan polusi udara. Ancaman bahaya penyakit pernapasan meningkat. Kondisi ini dipicu oleh apa?","opsi":["Rendahnya kerentanan masyarakat secara umum","Tingkat kapasitas pelayanan yang sangat rendah","Akses pelayanan kesehatan yang berlimpah","Meningkatnya ancaman/hazard lingkungan","Menurunnya jumlah penduduk usia produktif"],"jawabanBenar":3,"pembahasan":"Kebakaran hutan dan polusi udara ekstrem merupakan bentuk peningkatan hazard (ancaman bahaya eksternal) yang secara langsung memicu risiko gangguan kesehatan[cite: 1].","pembahasanPilihan":["Kerentanan yang rendah tidak memicu lonjakan kasus penyakit.","Kapasitas pelayanan tidak berhubungan langsung dengan sumber pemicu bencana eksternal.","Akses layanan yang banyak seharusnya menekan dampak, bukan memicu timbulnya ancaman.","Kebakaran hutan dan polusi udara ekstrem merupakan bentuk peningkatan hazard (ancaman bahaya eksternal) yang secara langsung memicu risiko gangguan kesehatan[cite: 1].","Jumlah penduduk tidak mengubah paparan polusi udara secara langsung."],"version":1},{"id":"kedkom2020-16","soal":"Ulama membolehkan penggunaan vaksin meskipun sebagian komponennya dibuat dari bahan yang tidak halal (najis/haram). Apakah dasar alasan utama penetapan hukum tersebut?","opsi":["Darurat, hajat, dan mashlahah bagi kehidupan manusia sebelum adanya bahan halal yang dapat menggantikannya","Tidak ada nash sama sekali yang mengharamkannya dalam Al-Qur'an","Mashlahah dan mafsadah bernilai sama persis dalam timbangan syariat","Vaksinasi belum pernah ditetapkan hukumnya oleh ulama mazhab klasik","Adanya nash shahih yang secara eksplisit membolehkan zat haram secara mutlak"],"jawabanBenar":0,"pembahasan":"Dalam kaidah fikih kesehatan Islam, penggunaan zat yang diharamkan dibolehkan dalam kondisi darurat atau hajat mendesak demi kemaslahatan umum (menjaga jiwa manusia) selama belum ada alternatif yang suci dan halal[cite: 1].","pembahasanPilihan":["Dalam kaidah fikih kesehatan Islam, penggunaan zat yang diharamkan dibolehkan dalam kondisi darurat atau hajat mendesak demi kemaslahatan umum (menjaga jiwa manusia) selama belum ada alternatif yang suci dan halal[cite: 1].","Terdapat kejelasan dalil mengenai keharaman zat tertentu, namun hukumnya menjadi longgar karena kaidah darurat.","Mashlahah (kemaslahatan) dalam hal ini jauh lebih besar daripada mafsadah.","Ijtihad kontemporer didasarkan pada prinsip adaptasi masalah kedokteran modern.","Zat haram tetap pada hukum asalnya kecuali ada uzur syar'i yang darurat."],"version":1},{"id":"kedkom2020-17","soal":"Indonesia mengalami masalah kesehatan dalam dekade terakhir dengan istilah 'triple burden disease'. Upaya apakah yang paling tepat dilakukan oleh tenaga kesehatan dalam meningkatkan pencegahan?","opsi":["Melakukan screening kesehatan hanya jika terjadi wabah besar di suatu wilayah","Menangani masalah kesehatan berbasis kuratif murni tanpa tindakan preventif","Menerapkan kebijakan holistik dan terpadu serta mengaplikasikan 5 level of prevention","Meningkatkan kesejahteraan ekonomi tenaga kesehatan semata tanpa edukasi warga","Fokus pada pengobatan rumah sakit tipe A"],"jawabanBenar":2,"pembahasan":"Menghadapi beban ganda penyakit (penyakit menular, tidak menular, dan penyakit re-emerging), pendekatan preventif melalui penerapan 5 level of prevention secara holistik dan terpadu adalah strategi utama[cite: 1].","pembahasanPilihan":["Skrining reaktif saat wabah tidak efektif membendung beban ganda penyakit.","Pendekatan kuratif murni akan membebani pembiayaan kesehatan secara masif.","Menghadapi beban ganda penyakit (penyakit menular, tidak menular, dan penyakit re-emerging), pendekatan preventif melalui penerapan 5 level of prevention secara holistik dan terpadu adalah strategi utama[cite: 1].","Kesejahteraan nakes penting, namun tidak menjawab substansi pencegahan penyakit di masyarakat.","Rumah sakit tipe A berfokus pada kuratif tersier, bukan pencegahan primer masyarakat."],"version":1},{"id":"kedkom2020-18","soal":"Pemberi pelayanan kesehatan sering kali dihadapkan pada risiko finansial akibat variasi utilisasi pelayanan peserta JKN. Hal ini merupakan kelemahan utama dari metode pembayaran apa?","opsi":["Service-based (Fee-for-service) dan population-based","Service-based (Fee-for-service) dan time-based","Timed-based dan case-based","Cased-based dan population-based","Population-based dan timed-based"],"jawabanBenar":1,"pembahasan":"Metode pembayaran imbalan jasa per pelayanan (fee-for-service / service-based) memicu risiko moral hazard dan pembengkakan biaya bagi penjamin karena volume tindakan tidak dibatasi oleh pagu tetap.","pembahasanPilihan":["Population-based memberikan risiko finansial pada pemberi layanan jika biaya melebihi kapitasi, namun service-based memindahkan risiko utilisasi ke pembayar.","Metode pembayaran imbalan jasa per pelayanan (fee-for-service / service-based) memicu risiko moral hazard dan pembengkakan biaya bagi penjamin karena volume tindakan tidak dibatasi oleh pagu tetap.","Time-based berfokus pada durasi kerja, bukan volume klinis langsung.","Case-based (seperti INA-CBG) justru mengendalikan biaya per paket episode penyakit.","Population-based mengalihkan risiko ke provider melalui sistem pra-upaya."],"version":1},{"id":"kedkom2020-19","soal":"Menurut para ulama kontemporer, pembolehan tindakan medis darurat seperti transfusi darah didasarkan pada tujuannya yang sejalan dengan maqashid syariah yaitu menciptakan kemaslahatan manusia dan menjaga nyawa dari kematian. Hal ini lazim disebut sebagai penjagaan terhadap apa?","opsi":["Hifzhul mal (Menjaga harta)","Hifzhul nafs (Menjaga jiwa)","Hifzhul aql (Menjaga akal)","Hifzhul nasl (Menjaga keturunan)","Hifzhul din (Menjaga agama)"],"jawabanBenar":1,"pembahasan":"Hifzhul nafs adalah prinsip pemeliharaan jiwa manusia dari ancaman kematian, kerusakan fisik, dan penyakit, yang menjadi dasar pembolehan tindakan darurat medis[cite: 1].","pembahasanPilihan":["Hifzhul mal berkaitan dengan perlindungan kepemilikan harta dan transaksi ekonomi.","Hifzhul nafs adalah prinsip pemeliharaan jiwa manusia dari ancaman kematian, kerusakan fisik, dan penyakit, yang menjadi dasar pembolehan tindakan darurat medis[cite: 1].","Hifzhul aql berkaitan dengan pemeliharaan fungsi kognitif dan larangan zat yang memabukkan.","Hifzhul nasl berkaitan dengan perlindungan garis keturunan dan kehormatan keluarga.","Hifzhul din berkaitan dengan pemeliharaan keyakinan akidah dan ibadah."],"version":1},{"id":"kedkom2020-20","soal":"Menurut syariat Islam, pelaksanaan rukun Islam seperti mendirikan shalat, menunaikan zakat, dan berpuasa merupakan bentuk pengamalan dari penjagaan terhadap apa?","opsi":["Hifzhud din (Menjaga agama)","Hifzhul mal (Menjaga harta)","Hifzhul nafs (Menjaga jiwa)","Hifzhul aql (Menjaga akal)","Hifzhul nasl (Menjaga keturunan)"],"jawabanBenar":0,"pembahasan":"Shalat, zakat, puasa, dan ibadah pokok lainnya merupakan pilar utama dalam menjaga eksistensi dan kemurnian agama Islam (Hifzhud din)[cite: 1].","pembahasanPilihan":["Shalat, zakat, puasa, dan ibadah pokok lainnya merupakan pilar utama dalam menjaga eksistensi dan kemurnian agama Islam (Hifzhud din)[cite: 1].","Hifzhul mal berkaitan dengan pengelolaan kekayaan, zakat harta termasuk di dalamnya dari sisi aset, namun ibadah mahdhah secara umum adalah pilar agama.","Hifzhul nafs berkaitan dengan keselamatan nyawa jasmani.","Hifzhul aql berkaitan dengan perlindungan akal pikiran.","Hifzhul nasl berkaitan dengan perlindungan sistem kekeluargaan."],"version":1},{"id":"kedkom2020-21","soal":"Bagaimanakah hukum Islam mengenai kewajiban menjaga kesehatan jasmani dan rohani bagi setiap muslim?","opsi":["Sunnah","Sunnah muakkadah","Wajib 'ain","Wajib kifayah","Mubah"],"jawabanBenar":2,"pembahasan":"Menjaga kesehatan jasmani dan rohani hukumnya wajib 'ain bagi setiap individu muslim karena tubuh adalah amanah yang harus dipelihara untuk beribadah[cite: 1].","pembahasanPilihan":["Menjaga kesehatan bukan sekadar anjuran ibadah sunnah karena menyangkut keselamatan raga.","Derajatnya melampaui sunnah muakkadah mengingat dampaknya langsung pada kemampuan menjalankan ibadah wajib.","Menjaga kesehatan jasmani dan rohani hukumnya wajib 'ain bagi setiap individu muslim karena tubuh adalah amanah yang harus dipelihara untuk beribadah[cite: 1].","Wajib kifayah gugur jika sudah dikerjakan orang lain, sedangkan penjagaan kesehatan diri bersifat personal.","Mubah berarti boleh dilakukan atau ditinggalkan, bertentangan dengan prinsip penjagaan jiwa."],"version":1},{"id":"kedkom2020-22","soal":"Manakah di bawah ini yang merupakan bagian dari karakteristik dan definisi pelayanan di Puskesmas?","opsi":["Mengutamakan upaya promotif dan preventif tanpa mengabaikan kuratif dan rehabilitatif","Mengutamakan pelayanan kuratif rawat inap subspesialistik tingkat lanjut","Hanya melayani kasus gawat darurat bedah mayor","Fokus pada pelayanan estetika dan kedokteran swasta komersial","Menolak pasien peserta jaminan kesehatan nasional"],"jawabanBenar":0,"pembahasan":"Puskesmas adalah fasilitas pelayanan kesehatan tingkat pertama yang menyelenggarakan upaya kesehatan masyarakat dan perorangan dengan mengutamakan promotif dan preventif[cite: 1].","pembahasanPilihan":["Puskesmas adalah fasilitas pelayanan kesehatan tingkat pertama yang menyelenggarakan upaya kesehatan masyarakat dan perorangan dengan mengutamakan promotif dan preventif[cite: 1].","Kuratif subspesialistik merupakan kewenangan rumah sakit rujukan tingkat lanjut.","Kasus bedah mayor ditangani di rumah sakit umum.","Puskesmas berorientasi pada pelayanan kesehatan publik dasar, bukan komersial estetika.","Puskesmas wajib melayani peserta JKN sesuai ketentuan yang berlaku."],"version":1},{"id":"kedkom2020-23","soal":"Di Indonesia banyak masyarakat menderita diare. Upaya pencegahan primer yang paling tepat dan mendasar untuk mencegah penularan diare adalah apa?","opsi":["Meminum obat antidiare setiap hari","Menerapkan higiene sanitasi total berbasis masyarakat seperti cuci tangan dan air bersih","Menjalani operasi saluran pencernaan preventif","Mengonsumsi antibiotik berspektrum luas secara rutin tanpa indikasi","Menghindari makan selamanya"],"jawabanBenar":1,"pembahasan":"Pencegahan diare paling efektif dilakukan melalui penyediaan air bersih, sanitasi yang layak, serta perilaku hidup bersih dan sehat (seperti mencuci tangan dengan sabun)[cite: 1].","pembahasanPilihan":["Obat antidiare adalah tata laksana kuratif/simptomatik, bukan pencegahan primer penularan.","Pencegahan diare paling efektif dilakukan melalui penyediaan air bersih, sanitasi yang layak, serta perilaku hidup bersih dan sehat (seperti mencuci tangan dengan sabun)[cite: 1].","Operasi tidak ada kaitannya dengan pencegahan diare.","Penggunaan antibiotik tanpa indikasi justru memicu resistensi kuman di saluran cerna.","Menghindari makan tidak masuk akal dan merusak nutrisi tubuh."],"version":1},{"id":"kedkom2020-24","soal":"Kegiatan riset kesehatan masyarakat nasional yang memusatkan tujuan salah satunya pada evaluasi pencapaian target pembangunan milenium (MDG's) di Indonesia adalah:","opsi":["Riskesdas 2007","Riskesdas 2013","Susenas Kor","SKRT murni","Survei Ekonomi Pertanian"],"jawabanBenar":1,"pembahasan":"Riset Kesehatan Dasar (Riskesdas) tahun 2013 dirancang secara spesifik untuk memotret dan mengevaluasi pencapaian target Millenium Development Goals (MDG's) bidang kesehatan di Indonesia[cite: 1].","pembahasanPilihan":["Riskesdas 2007 merupakan baseline awal riset kesehatan dasar nasional.","Riset Kesehatan Dasar (Riskesdas) tahun 2013 dirancang secara spesifik untuk memotret dan mengevaluasi pencapaian target Millenium Development Goals (MDG's) bidang kesehatan di Indonesia[cite: 1].","Susenas lebih berfokus pada sosial ekonomi makro rumah tangga.","SKRT adalah survei pendahulu sebelum era Riskesdas masif.","Survei pertanian tidak menilai indikator kesehatan manusia."],"version":1},{"id":"kedkom2020-25","soal":"Upaya menghentikan praktik buang air besar sembarangan (open defecation free) merupakan satu dari lima pilar STBM untuk mencegah risiko water-borne disease. Kegiatan di atas mendukung pencapaian target SDGs nomor berapa?","opsi":["Tujuan 1 dan 2","Tujuan 3 dan 6","Tujuan 5 dan 8","Tujuan 7 dan 12","Tujuan 9 dan 14"],"jawabanBenar":1,"pembahasan":"Sanitasi total dan air bersih berkaitan langsung dengan Tujuan 3 (Good Health and Well-being / Kehidupan sehat dan sejahtera) dan Tujuan 6 (Clean Water and Sanitation / Air bersih dan sanitasi layak)[cite: 1].","pembahasanPilihan":["Tujuan 1 dan 2 berkaitan dengan pengentasan kemiskinan dan kelaparan.","Sanitasi total dan air bersih berkaitan langsung dengan Tujuan 3 (Good Health and Well-being / Kehidupan sehat dan sejahtera) dan Tujuan 6 (Clean Water and Sanitation / Air bersih dan sanitasi layak)[cite: 1].","Tujuan 5 dan 8 berkaitan dengan kesetaraan gender dan pertumbuhan ekonomi.","Tujuan 7 dan 12 berkaitan dengan energi bersih serta konsumsi berkelanjutan.","Tujuan 9 dan 14 berkaitan dengan infrastruktur industri dan ekosistem lautan."],"version":1},{"id":"kedkom2020-26","soal":"Seorang wanita berusia 22 tahun datang ke puskesmas dengan keluhan demam dan gusi berdarah. Agar tidak terjadi peningkatan kasus, dokter puskesmas melakukan penyuluhan kepada masyarakat sekitar rumah pasien mengenai penyakit tersebut melalui pemutaran film edukasi. Apakah peran utama yang sedang dijalankan oleh dokter tersebut?","opsi":["Care provider","Manager pelayanan","Gate keeper","Communicator / Educator","Community leader"],"jawabanBenar":3,"pembahasan":"Melakukan penyuluhan dan edukasi menggunakan media audio-visual kepada masyarakat mencerminkan peran dokter sebagai komunikator dan edukator kesehatan masyarakat[cite: 1].","pembahasanPilihan":["Care provider adalah peran saat dokter memeriksa dan mengobati pasien secara langsung di ruang praktik.","Manager berkaitan dengan pengaturan administrasi dan sumber daya fasilitas kesehatan.","Gate keeper adalah fungsi penjaga gerbang rujukan layanan primer BPJS.","Melakukan penyuluhan dan edukasi menggunakan media audio-visual kepada masyarakat mencerminkan peran dokter sebagai komunikator dan edukator kesehatan masyarakat[cite: 1].","Community leader adalah peran memimpin komunitas secara struktural formal."],"version":1},{"id":"kedkom2020-27","soal":"Penjelasan mengenai kondisi Indonesia yang saat ini mengalami 'triple burden disease' (penyakit menular, penyakit tidak menular, dan penyakit re-emerging). Pertanyaannya, masalah gizi apakah yang sampai saat ini masih menjadi beban utama di Indonesia?","opsi":["Stunting, wasting, dan gizi kurang","Gizi lebih dan obesitas semata","Defisiensi vitamin murni","Kekurangan yodium absolut","Hiperkolesterolemia adolesen"],"jawabanBenar":0,"pembahasan":"Masalah gizi utama di Indonesia yang persisten menyusun beban ganda nutrisi meliputi stunting (pendek), wasting (kurus), gizi kurang, serta masalah mikronutrien[cite: 1].","pembahasanPilihan":["Masalah gizi utama di Indonesia yang persisten menyusun beban ganda nutrisi meliputi stunting (pendek), wasting (kurus), gizi kurang, serta masalah mikronutrien[cite: 1].","Gizi lebih memang meningkat, namun masalah kekurangan gizi kronis seperti stunting masih menjadi fokus utama.","Defisiensi vitamin tidak berdiri sendiri tanpa masalah antropometri makro.","Kekurangan yodium sudah banyak teratasi melalui program iodisasi garam.","Hiperkolesterolemia merupakan bagian kecil dari profil metabolik dewasa."],"version":1},{"id":"kedkom2020-28","soal":"Peraturan Menteri Kesehatan manakah yang menjadi acuan hukum operasional dalam penyelenggaraan Puskesmas secara nasional?","opsi":["Permenkes No. 23 Tahun 2014","Permenkes No. 43 Tahun 2019","Permenkes No. 23 Tahun 2019","Permenkes No. 75 Tahun 2015","Permenkes No. 9 Tahun 2021"],"jawabanBenar":1,"pembahasan":"Peraturan Menteri Kesehatan Nomor 43 Tahun 2019 adalah regulasi sah dan berlaku yang mengatur tentang Puskesmas pengganti regulasi terdahulu[cite: 1].","pembahasanPilihan":["Permenkes 23 Tahun 2014 tidak mengatur tentang Puskesmas.","Peraturan Menteri Kesehatan Nomor 43 Tahun 2019 adalah regulasi sah dan berlaku yang mengatur tentang Puskesmas pengganti regulasi terdahulu[cite: 1].","Permenkes 23 Tahun 2019 bukan peraturan tentang Puskesmas.","Permenkes 75 Tahun 2015 bukan nomor yang tepat (yang benar nomor 75 Tahun 2014, namun telah diperbarui oleh Permenkes 43 Tahun 2019).","Permenkes 9 Tahun 2021 mengatur substansi lain."],"version":1},{"id":"kedkom2020-29","soal":"Kepala Puskesmas A akan melakukan evaluasi program. Ia menentukan prioritas masalah dengan mengumpulkan semua tenaga kesehatan di Puskesmas A yaitu dokter umum, bidan, apoteker, sanitarian, dan staf lainnya. Metode penentuan prioritas apa yang menggunakan musyawarah kelompok ahli seperti ini?","opsi":["Metode MCUA (Matrix Criteria Utility Analysis)","Metode PAHO","Metode Delphi","Metode Delbecq (Nominal Group Technique / NGT)","Metode Hanlon kuantitatif"],"jawabanBenar":3,"pembahasan":"Metode Delbecq (atau Nominal Group Technique) mempertemukan langsung para tenaga ahli dari berbagai latar belakang profesi untuk berdiskusi dan melakukan perangkingan prioritas masalah secara tatap muka[cite: 1].","pembahasanPilihan":["MCUA menggunakan pembobotan matriks kriteria penilaian bernumerik.","Metode PAHO menggunakan kriteria besaran dan kegawatan.","Metode Delphi menggunakan kuesioner berulang tanpa mempertemukan langsung para ahli dalam satu forum fisik.","Metode Delbecq (atau Nominal Group Technique) mempertemukan langsung para tenaga ahli dari berbagai latar belakang profesi untuk berdiskusi dan melakukan perangkingan prioritas masalah secara tatap muka[cite: 1].","Hanlon menggunakan rumus matematis perhitungan nilai prioritas."],"version":1},{"id":"kedkom2020-30","soal":"Covid-19 telah mereda dan wabah dinyatakan terkendali. Masyarakat mulai membangun kembali kesehatan dan ekonominya secara perlahan. Fase apakah dalam siklus manajemen bencana yang sedang dilalui masyarakat saat ini?","opsi":["Fase Transisi darurat menuju pemulihan (pasca krisis)","Fase Siaga tanggap darurat","Fase Mitigasi bencana awal","Fase Kontingensi reaktif","Fase Impact langsung"],"jawabanBenar":0,"pembahasan":"Fase transisi darurat ke pemulihan (pasca krisis) adalah masa ketika ancaman akut mereda dan masyarakat mulai menata kembali kehidupan sosial, ekonomi, serta pelayanan kesehatannya[cite: 1].","pembahasanPilihan":["Fase transisi darurat ke pemulihan (pasca krisis) adalah masa ketika ancaman akut mereda dan masyarakat mulai menata kembali kehidupan sosial, ekonomi, serta pelayanan kesehatannya[cite: 1].","Siaga tanggap darurat adalah fase saat bencana sedang berlangsung aktif.","Mitigasi dilakukan jauh sebelum bencana terjadi untuk mengurangi risiko.","Kontingensi adalah perencanaan kesiapsiagaan sebelum krisis.","Impact adalah saat terjadinya hantaman bencana."],"version":1},{"id":"kedkom2020-31","soal":"Rendahnya kesadaran masyarakat tentang kesehatan ibu hamil menjadi penentu tingginya angka kematian di wilayah kerja dokter Z. Untuk itu, dokter Z melakukan pelayanan kesehatan komprehensif meliputi ANC rutin, senam hamil, dan mengingatkan pentingnya pendampingan keluarga. Kompetensi dokter manakah yang sedang dijalankan oleh dokter Z?","opsi":["Researcher (Peneliti klinis)","Educator (Pendidik masyarakat)","Manager program","Health care provider (Pemberi pelayanan kesehatan)","Decision maker"],"jawabanBenar":3,"pembahasan":"Melakukan pemeriksaan langsung (ANC), pelayanan klinis komprehensif, dan intervensi medis kepada pasien merupakan wujud utama kompetensi sebagai Health Care Provider (Pemberi pelayanan kesehatan)[cite: 1].","pembahasanPilihan":["Researcher berfokus pada penelitian ilmiah dan uji klinis.","Educator berfokus pada pengajaran teori edukasi kesehatan semata.","Manager mengatur manajemen administratif faskes.","Melakukan pemeriksaan langsung (ANC), pelayanan klinis komprehensif, dan intervensi medis kepada pasien merupakan wujud utama kompetensi sebagai Health Care Provider (Pemberi pelayanan kesehatan)[cite: 1].","Decision maker adalah pengambil kebijakan tingkat lanjut."],"version":1},{"id":"kedkom2020-32","soal":"Saat melakukan evaluasi program, dokter X menemukan masalah berupa rendahnya cakupan pemberian ASI eksklusif di wilayah kerjanya akibat keterbatasan jumlah tenaga penyuluh gizi. Berdasarkan analisis sistem, termasuk ke dalam subsistem manakah masalah tersebut?","opsi":["Man (Sumber daya manusia)","Money (Anggaran dana)","Method (Metode kerja)","Environment (Lingkungan sosial)","Material (Sarana logistik)"],"jawabanBenar":0,"pembahasan":"Keterbatasan jumlah dan kapasitas tenaga kesehatan (petugas gizi/penyuluh) dikategorikan sebagai hambatan pada subsistem Man (manusia/SDM)[cite: 1].","pembahasanPilihan":["Keterbatasan jumlah dan kapasitas tenaga kesehatan (petugas gizi/penyuluh) dikategorikan sebagai hambatan pada subsistem Man (manusia/SDM)[cite: 1].","Money berkaitan dengan kecukupan anggaran dan pembiayaan program.","Method berkaitan dengan prosedur tetap, SOP, atau teknik pelaksanaan kegiatan.","Environment berkaitan dengan kondisi cuaca, geografis, atau sosial budaya eksternal.","Material berkaitan dengan ketersediaan alat, obat, dan bahan penunjang fisik."],"version":1},{"id":"kedkom2020-33","soal":"Upaya kesehatan di Puskesmas harus senantiasa berkaitan dengan sumber daya yang tersedia dan prioritas masalah yang menjadi beban nyata masyarakat di wilayah kerjanya. Upaya kesehatan apakah yang menjadi fokus utama dasar tersebut?","opsi":["Upaya Kesehatan Ibu dan Anak (KIA) serta Gizi masyarakat","Upaya pelayanan bedah kosmetik lanjutan","Upaya kedokteran penerbangan komersial","Upaya transplantasi organ tubuh langka","Upaya pariwisata medis internasional"],"jawabanBenar":0,"pembahasan":"Pelayanan dasar esensial di Puskesmas menempatkan KIA dan Gizi masyarakat sebagai pilar utama karena besarnya dampak terhadap derajat kesehatan kelompok rentan di wilayah kerja[cite: 1].","pembahasanPilihan":["Pelayanan dasar esensial di Puskesmas menempatkan KIA dan Gizi masyarakat sebagai pilar utama karena besarnya dampak terhadap derajat kesehatan kelompok rentan di wilayah kerja[cite: 1].","Bedah kosmetik merupakan layanan estetik sekunder/tersier.","Kedokteran penerbangan bukan lingkup dasar Puskesmas.","Transplantasi organ memerlukan fasilitas rumah sakit rujukan tingkat tinggi.","Pariwisata medis bukan bagian dari pelayanan publik primer dasar."],"version":1},{"id":"kedkom2020-34","soal":"Kepala Puskesmas melakukan lokakarya mini. Dalam menentukan prioritas masalah kesehatan, diberikan pembobotan nilai (skor) dari masing-masing kriteria penilaian yang telah disepakati. Termasuk ke dalam metode apakah teknik penentuan prioritas tersebut?","opsi":["Metode Delphi kualitatif","Metode MCUA (Matrix Criteria Utility Analysis)","Metode observasi langsung","Metode potong lintang","Metode survei acak"],"jawabanBenar":1,"pembahasan":"Metode MCUA (Matrix Criteria Utility Analysis) menggunakan pembobotan nilai pada berbagai kriteria penentu untuk menghasilkan skor akhir prioritas masalah secara objektif[cite: 1].","pembahasanPilihan":["Metode Delphi tidak menggunakan matriks pembobotan skor numerik terbuka bersama.","Metode MCUA (Matrix Criteria Utility Analysis) menggunakan pembobotan nilai pada berbagai kriteria penentu untuk menghasilkan skor akhir prioritas masalah secara objektif[cite: 1].","Observasi adalah teknik pengumpulan data, bukan metode penentuan prioritas manajemen.","Potong lintang adalah desain studi epidemiologi.","Survei acak adalah metode sampling data."],"version":1},{"id":"kedkom2020-35","soal":"Terdapat kasus gusi gigi berdarah pada warga. Sebagai dokter puskesmas, Anda ingin melakukan penyuluhan dengan cara memutarkan film edukasi agar kasus tersebut tidak meningkat kembali. Peran apakah yang sedang dijalankan oleh dokter tersebut?","opsi":["Community leader formal","Communicator / Educator kesehatan","Manager administratif","Care provider klinis murni","Financial auditor"],"jawabanBenar":1,"pembahasan":"Memberikan penyuluhan dan menyampaikan pesan kesehatan melalui media audio-visual (film) menempatkan dokter dalam peran sebagai komunikator dan edukator kesehatan[cite: 1].","pembahasanPilihan":["Community leader adalah pemimpin sosial kemasyarakatan.","Memberikan penyuluhan dan menyampaikan pesan kesehatan melalui media audio-visual (film) menempatkan dokter dalam peran sebagai komunikator dan edukator kesehatan[cite: 1].","Manager mengurusi tata kelola instansi.","Care provider mengobati pasien secara individual di ruang periksa.","Financial auditor memeriksa keuangan."],"version":1},{"id":"kedkom2020-36","soal":"Lembaga atau survei nasional berbasis komunitas manakah yang secara historis sering digunakan di Indonesia untuk mengevaluasi indikator kesehatan dan pencapaian program?","opsi":["Survei Kesehatan Rumah Tangga (SKRT) / Riskesdas","Sensus penduduk industri berat","Survei lalu lintas darat nasional","Sensus perusahaan ekspor impor","Survei geologi pertambangan"],"jawabanBenar":0,"pembahasan":"Survei Kesehatan Rumah Tangga (SKRT) dan Riset Kesehatan Dasar (Riskesdas) adalah instrumen riset kesehatan nasional berbasis komunitas utama di Indonesia[cite: 1].","pembahasanPilihan":["Survei Kesehatan Rumah Tangga (SKRT) dan Riset Kesehatan Dasar (Riskesdas) adalah instrumen riset kesehatan nasional berbasis komunitas utama di Indonesia[cite: 1].","Sensus industri tidak menilai status kesehatan.","Lalu lintas berkaitan dengan perhubungan darat.","Perusahaan ekspor impor diurus kementerian perdagangan.","Geologi diurus kementerian ESDM."],"version":1},{"id":"kedkom2020-37","soal":"Berdasarkan program pengendalian penyakit menular di puskesmas, terjadi peningkatan kasus HIV/AIDS sebesar 50%, namun tidak sejalan dengan akses pengobatan ARV yang hanya 10%. Koordinator menganjurkan untuk dilakukan konseling kelompok. Siapakah pihak yang paling tepat diundang pada konseling kelompok kasus tersebut?","opsi":["Kader kesehatan, ODHIV, dan petugas layanan kesehatan","Hanya aparat kepolisian dan camat setempat","Seluruh warga desa tanpa terkecuali","Hanya petugas laboratorium rujukan pusat","Anak-anak sekolah dasar wilayah setempat"],"jawabanBenar":0,"pembahasan":"Konseling kelompok untuk penanggulangan hambatan HIV/AIDS melibatkan Orang Dengan HIV (ODHIV), kader pendukung, serta petugas layanan kesehatan agar tercipta komunikasi dua arah yang suportif[cite: 1].","pembahasanPilihan":["Konseling kelompok untuk penanggulangan hambatan HIV/AIDS melibatkan Orang Dengan HIV (ODHIV), kader pendukung, serta petugas layanan kesehatan agar tercipta komunikasi dua arah yang suportif[cite: 1].","Aparat kepolisian dapat memicu stigma dan melanggar kerahasiaan medis pasien.","Melibatkan seluruh warga desa melanggar asas kerahasiaan medis (confidentiality).","Petugas lab tidak menangani proses konseling psikososial kelompok.","Anak sekolah tidak relevan dengan sasaran konseling HIV."],"version":1},{"id":"kedkom2020-38","soal":"Di Indonesia, angka perkawinan di bawah usia 15 tahun masih ditemukan. Kondisi ini memberikan dampak negatif utama terhadap aspek apa?","opsi":["Kesehatan reproduksi remaja (KRR) dan risiko komplikasi obstetrik","Peningkatan cadangan devisa negara secara instan","Penurunan angka urbanisasi penduduk desa","Penguatan struktur ekonomi makro keluarga","Stabilitas harga pasar domestik"],"jawabanBenar":0,"pembahasan":"Pernikahan dini berdampak buruk langsung pada Kesehatan Reproduksi Remaja (KRR), meningkatkan risiko kematian ibu/bayi, serta masalah psikososial[cite: 1].","pembahasanPilihan":["Pernikahan dini berdampak buruk langsung pada Kesehatan Reproduksi Remaja (KRR), meningkatkan risiko kematian ibu/bayi, serta masalah psikososial[cite: 1].","Pernikahan dini tidak berkaitan dengan devisa negara.","Tidak ada korelasi langsung dengan penurunan urbanisasi.","Secara ekonomi, pernikahan dini justru sering melanggengkan siklus kemiskinan keluarga.","Tidak berpengaruh pada stabilitas harga pasar."],"version":1},{"id":"kedkom2020-39","soal":"Skrining perkembangan anak usia dini yang sederhana, cepat, dan dapat dilakukan di puskesmas, oleh orang tua, atau guru PAUD menggunakan instrumen apa?","opsi":["Kuesioner Pra Skrining Perkembangan (KPSP)","Kuesioner GPPH untuk hiperaktif","Skala Bayley-III klinis mendalam","Tes Denver II psikolog lanjutan","Kuesioner PEDS psikiatrik"],"jawabanBenar":0,"pembahasan":"Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi Kemenkes yang mudah digunakan oleh tenaga kesehatan dasar, guru PAUD, maupun orang tua untuk memantau perkembangan anak[cite: 1].","pembahasanPilihan":["Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi Kemenkes yang mudah digunakan oleh tenaga kesehatan dasar, guru PAUD, maupun orang tua untuk memantau perkembangan anak[cite: 1].","GPPH khusus untuk deteksi gangguan pemusatan perhatian dan hiperaktivitas.","Bayley Scale adalah alat uji psikometrik klinis yang rumit dan memakan waktu lama.","Denver II memerlukan pelatihan khusus dan waktu pemeriksaan yang lebih panjang dibanding KPSP sederhana.","PEDS instrumen skrining perilaku berbasis laporan orang tua, namun KPSP adalah standar primer nasional."],"version":1},{"id":"kedkom2020-40","soal":"Dalam sepuluh tahun terakhir, penyakit tidak menular (PTM) meningkat baik di negara berkembang maupun maju, bukan cuma penyakit degeneratif tetapi juga masalah kesehatan jiwa seperti depresi dan kecemasan berat. Apakah faktor sosiologis utama yang memicu hal ini?","opsi":["Kesenjangan pemenuhan kebutuhan hidup, stres modern, dan perubahan struktur sosial","Keberhasilan program imunisasi balita nasional","Penurunan jumlah fasilitas rumah sakit modern","Ketiadaan sama sekali penyakit menular di bumi","Pemberian makanan bayi ASI eksklusif"],"jawabanBenar":0,"pembahasan":"Peningkatan masalah kejiwaan dan PTM modern erat kaitannya dengan tekanan hidup urban, kesenjangan sosial, stres ekonomi, serta perubahan gaya hidup masyarakat[cite: 1].","pembahasanPilihan":["Peningkatan masalah kejiwaan dan PTM modern erat kaitannya dengan tekanan hidup urban, kesenjangan sosial, stres ekonomi, serta perubahan gaya hidup masyarakat[cite: 1].","Imunisasi justru mencegah penyakit infeksi, bukan memicu gangguan jiwa.","Fasilitas rumah sakit yang bertambah tidak memicu stres psikis.","Penyakit menular masih ada.","ASI eksklusif berdampak positif bagi tumbuh kembang anak."],"version":1},{"id":"kedkom2020-41","soal":"Seorang dokter memperhatikan banyak anak remaja perempuan yang mengalami keluhan pucat dan lemas saat menstruasi, lalu dokter memberikan suplemen zat besi serta edukasi nutrisi. Termasuk ke dalam tingkat pencegahan (level of prevention) apakah tindakan dokter tersebut?","opsi":["Health promotion dan Specific protection (Pencegahan primer)","Early diagnosis and prompt treatment (Pencegahan sekunder)","Disability limitation","Rehabilitation medis total","Paliatif terminal"],"jawabanBenar":1,"pembahasan":"Memberikan skrining anemia serta intervensi pengobatan dini (zat besi) pada kelompok yang sudah menunjukkan gejala awal (pucat/lemas haid) termasuk dalam Early diagnosis and prompt treatment (Pencegahan sekunder)[cite: 1].","pembahasanPilihan":["Pencegahan primer dilakukan sebelum seseorang sakit (misal: penyuluhan umum).","Memberikan skrining anemia serta intervensi pengobatan dini (zat besi) pada kelompok yang sudah menunjukkan gejala awal (pucat/lemas haid) termasuk dalam Early diagnosis and prompt treatment (Pencegahan sekunder)[cite: 1].","Disability limitation mencegah kecacatan lanjut dari penyakit berat.","Rehabilitasi memulihkan fungsi tubuh pasca sakit berat.","Paliatif merawat pasien terminal."],"version":1},{"id":"kedkom2020-42","soal":"Ulama memperbolehkan penggunaan vaksin yang mengandung unsur najis atau haram dalam proses pembuatannya apabila berada dalam kondisi apa?","opsi":["Darurat dan hajat mendesak demi kemaslahatan umat (hifzhul nafs)","Keinginan perusahaan farmasi komersial semata","Ketiadaan aturan hukum tertulis dalam perundang-undangan","Kelonggaran budaya global modern","Bukan merupakan kewajiban ibadah mahdhah"],"jawabanBenar":0,"pembahasan":"Kaidah darurat dan hajat mendesak untuk melindungi jiwa manusia (hifzhul nafs) dari ancaman wabah mematikan membolehkan penggunaan zat yang hukum asalnya haram jika belum ada pengganti yang suci[cite: 1].","pembahasanPilihan":["Kaidah darurat dan hajat mendesak untuk melindungi jiwa manusia (hifzhul nafs) dari ancaman wabah mematikan membolehkan penggunaan zat yang hukum asalnya haram jika belum ada pengganti yang suci[cite: 1].","Kepentingan komersial semata tidak menghalalkan yang haram.","Hukum Islam didasarkan pada dalil syar'i dan kaidah fiqih, bukan sekadar administrasi.","Budaya global tidak menjadi sumber hukum syariat.","Alasan ibadah mahdhah tidak relevan dengan zat vaksin."],"version":1},{"id":"kedkom2020-43","soal":"Seorang anak laki-laki umur 2 tahun 1 bulan mengalami gizi buruk dan keterlambatan perkembangan, dengan latar belakang keluarga pemulung. Di manakah tatalaksana awal kegawatdaruratan gizi buruk dan komplikasi medis dapat dilakukan?","opsi":["Fasilitas rujukan rumah sakit (RSUD/RS rujukan) sesuai protokol rawat inap gizi buruk","Dilakukan sepenuhnya secara mandiri di rumah oleh tetangga","Hanya di taman bermain anak PAUD","Dibiarkan tanpa penanganan hingga usia dewasa","Diserahkan pada dukun kampung setempat"],"jawabanBenar":0,"pembahasan":"Kasus gizi buruk dengan komplikasi atau keterlambatan berat memerlukan tatalaksana medis komprehensif di fasilitas pelayanan kesehatan rujukan (Puskesmas rawat inap atau RSUD) sesuai pedoman tatalaksana anak gizi buruk[cite: 1].","pembahasanPilihan":["Kasus gizi buruk dengan komplikasi atau keterlambatan berat memerlukan tatalaksana medis komprehensif di fasilitas pelayanan kesehatan rujukan (Puskesmas rawat inap atau RSUD) sesuai pedoman tatalaksana anak gizi buruk[cite: 1].","Penanganan gizi buruk membutuhkan protokol medis klinis ketat yang tidak bisa di rumah.","PAUD tidak memiliki fasilitas medis terapeutik.","Membiarkan gizi buruk berisiko tinggi menyebabkan kematian anak.","Dukun tidak memiliki kompetensi medis klinis gizi."],"version":1},{"id":"kedkom2020-44","soal":"Nilai gotong royong dan kebersamaan di masyarakat dapat membantu menyelesaikan masalah kesehatan serta meningkatkan kesehatan mental warga. Berdasarkan kerangka sosiologis budaya, hal tersebut masuk ke dalam aspek apa?","opsi":["Suprastruktur (Sistem nilai, norma, ideologi, dan pandangan hidup)","Infrastruktur ekonomi produksi","Struktur organisasi birokrasi formal","Subsistem finansial perbankan","Sistem logistik material"],"jawabanBenar":0,"pembahasan":"Gotong royong, norma sosial, nilai moral, dan ideologi kebersamaan masyarakat dikategorikan dalam aspek suprastruktur budaya[cite: 1].","pembahasanPilihan":["Gotong royong, norma sosial, nilai moral, dan ideologi kebersamaan masyarakat dikategorikan dalam aspek suprastruktur budaya[cite: 1].","Infrastruktur berkaitan dengan basis materi dan produksi ekonomi.","Struktur berkaitan dengan tata kelola kelembagaan formal.","Finansial berkaitan dengan perputaran uang.","Logistik berkaitan dengan barang fisik."],"version":1},{"id":"kedkom2020-45","soal":"Seorang ibu baru saja melahirkan bayinya secara spontan. Sesaat setelah lahir, bayi diletakkan tengkurap di atas perut atau dada ibu setelah dikeringkan (Inisiasi Menyusui Dini / IMD). Apakah tujuan utama bayi ditetapkan tengkurap di perut ibunya?","opsi":["Kontak kulit bayi dengan kulit ibu (skin-to-skin contact) untuk kehangatan dan kolonisasi kuman baik","Memastikan berat badan bayi langsung bertambah drastis","Agar bayi langsung tertidur pulas dan tidak bernapas","Menghindari ibu melihat wajah bayinya","Memudahkan dokter menjahit luka jalan lahir"],"jawabanBenar":0,"pembahasan":"Tujuan utama IMD melalui kontak kulit dengan kulit (skin-to-skin contact) adalah menjaga kestabilan suhu tubuh bayi, melatih refleks hisap dini, serta transfer kolonisasi flora normal ibu[cite: 1].","pembahasanPilihan":["Tujuan utama IMD melalui kontak kulit dengan kulit (skin-to-skin contact) adalah menjaga kestabilan suhu tubuh bayi, melatih refleks hisap dini, serta transfer kolonisasi flora normal ibu[cite: 1].","IMD tidak langsung menaikkan berat badan secara instan.","Bayi diarahkan untuk aktif mencari puting, bukan tidur tanpa respon.","Ibu justru dianjurkan berinteraksi penuh dengan bayinya.","Posisi bayi di perut/dada tidak mengganggu proses penjahitan perineum secara langsung."],"version":1},{"id":"kedkom2020-46","soal":"Upaya praktik buang air besar sembarangan (open defecation) merupakan salah satu dari lima pilar STBM untuk mengurangi risiko terjadinya water-borne disease seperti diare. Kegiatan di atas mendukung pencapaian SDGs nomor berapa?","opsi":["Tujuan 3 (Kehidupan sehat) dan Tujuan 6 (Air bersih dan sanitasi)","Tujuan 1 dan Tujuan 2","Tujuan 4 dan Tujuan 5","Tujuan 8 dan Tujuan 9","Tujuan 10 dan Tujuan 11"],"jawabanBenar":0,"pembahasan":"Pemberantasan buang air besar sembarangan berkaitan langsung dengan Tujuan 3 (Good Health and Well-being) dan Tujuan 6 (Clean Water and Sanitation) dalam SDGs[cite: 1].","pembahasanPilihan":["Pemberantasan buang air besar sembarangan berkaitan langsung dengan Tujuan 3 (Good Health and Well-being) dan Tujuan 6 (Clean Water and Sanitation) dalam SDGs[cite: 1].","Tujuan 1 dan 2 untuk kemiskinan dan kelaparan.","Tujuan 4 dan 5 untuk pendidikan dan kesetaraan gender.","Tujuan 8 dan 9 untuk ekonomi dan industri.","Tujuan 10 dan 11 untuk kesenjangan dan kota berkelanjutan."],"version":1},{"id":"kedkom2020-47","soal":"Seorang anak laki-laki berusia 2 tahun 1 bulan, BB 8.5 kg dan PB 70 cm datang dengan keluhan BAB mencret sejak 1 bulan. Anak tidak mau makan dan hanya mendapatkan ASI. Belum bisa duduk dan berjalan, hanya bisa bicara 'mama-papa'. Orang tua pemulung dengan 5 anak. Apakah diagnosis masalah medis anak tersebut?","opsi":["Gizi buruk dengan keterlambatan perkembangan global (global developmental delay)","Gizi kurang dengan keterlambatan motorik halus","Gizi baik dengan tumbuh kembang normal","Obesitas anak dengan retardasi","Marasmus ringan tanpa gangguan motorik"],"jawabanBenar":0,"pembahasan":"Antropometri BB/PB < -3 SD menunjukkan gizi buruk, dan keterlambatan di berbagai milestone (motorik kasar, bicara, adaptif sosial) menunjukkan keterlambatan perkembangan global[cite: 1].","pembahasanPilihan":["Antropometri BB/PB < -3 SD menunjukkan gizi buruk, dan keterlambatan di berbagai milestone (motorik kasar, bicara, adaptif sosial) menunjukkan keterlambatan perkembangan global[cite: 1].","Status gizi anak sudah masuk kategori gizi buruk, bukan gizi kurang.","Data berat badan dan tinggi badan jauh di bawah standar normal.","Anak mengalami kekurangan gizi parah, bukan obesitas.","Keterlambatan motorik anak sangat nyata (belum bisa duduk/jalan di usia 2 tahun).IY"],"version":1},{"id":"kedkom2020-48","soal":"Kegiatan riset kesehatan nasional yang dilakukan untuk mengevaluasi target MDGs di bidang kesehatan secara komprehensif adalah:","opsi":["Riskesdas 2013","Susenas umum kor","Survei demografi industri","Sensus ekonomi nasional","Survei angkatan kerja"],"jawabanBenar":0,"pembahasan":"Riskesdas 2013 dirancang khusus untuk memantau pencapaian indikator kesehatan dalam target MDGs di Indonesia[cite: 1].","pembahasanPilihan":["Riskesdas 2013 dirancang khusus untuk memantau pencapaian indikator kesehatan dalam target MDGs di Indonesia[cite: 1].","Susenas berfokus pada sosial ekonomi makro.","Demografi industri bukan survei kesehatan.","Sensus ekonomi mencatat perdagangan.","Survei angkatan kerja mencatat ketenagakerjaan."],"version":1},{"id":"kedkom2020-49","soal":"Indonesia merupakan salah satu negara dengan angka perkawinan anak yang tinggi. Dari berbagai faktor sosiologis, manakah yang paling berkontribusi langsung terhadap peningkatan pernikahan dini?","opsi":["Kehamilan yang tidak direncanakan / kehamilan remaja di luar nikah serta norma sosial budaya","Kewajiban melanjutkan pendidikan tinggi universitas","Ketersediaan fasilitas perumahan gratis bagi remaja","Kebijakan wajib militer bagi seluruh perempuan","Penurunan populasi penduduk secara drastis"],"jawabanBenar":0,"pembahasan":"Faktor utama pendorong perkawinan anak di Indonesia meliputi kehamilan yang tidak direncanakan di kalangan remaja, faktor ekonomi, serta tekanan norma budaya lokal[cite: 1].","pembahasanPilihan":["Faktor utama pendorong perkawinan anak di Indonesia meliputi kehamilan yang tidak direncanakan di kalangan remaja, faktor ekonomi, serta tekanan norma budaya lokal[cite: 1].","Kewajiban kuliah justru menunda usia perkawinan.","Perumahan gratis tidak memicu pernikahan dini.","Indonesia tidak menerapkan wajib militer.","Populasi Indonesia bertambah, bukan menurun."],"version":1},{"id":"kedkom2020-50","soal":"Keluarga inti yang harmonis dapat memberikan dukungan sosial yang berdampak positif pada kesehatan anggota keluarga. Sebaliknya, keluarga yang disfungsional dapat menimbulkan stres kronis dan konflik. Berdasarkan sistem sosiologi budaya, keluarga termasuk ke dalam aspek apa?","opsi":["Struktur (Lembaga sosial / institusi kemasyarakatan)","Infrastruktur ekonomi","Suprastruktur ideologi filosofis","Multistruktur global","Sub-kultur artifisial"],"jawabanBenar":0,"pembahasan":"Keluarga sebagai unit institusi sosial kemasyarakatan terkecil dikategorikan dalam aspek struktur sosial masyarakat[cite: 1].","pembahasanPilihan":["Keluarga sebagai unit institusi sosial kemasyarakatan terkecil dikategorikan dalam aspek struktur sosial masyarakat[cite: 1].","Infrastruktur berkaitan dengan modal ekonomi material.","Suprastruktur berkaitan dengan sistem nilai dan keyakinan abstrak.","Multistruktur bukan istilah baku dalam stratifikasi sosiologi budaya.","Sub-kultur adalah kelompok budaya bagian."],"version":1},{"id":"kedkom2020-51","soal":"Seorang anak umur 2 tahun 1 bulan, BB 8.5 kg dan PB 70 cm dengan keluhan BAB mencret 1 bulan. Belum bisa duduk dan berdiri, bicara mama-papa. Orang tua pemulung dengan 5 anak kecil. Di manakah tatalaksana awal gizi buruk dan keterlambatan perkembangan tersebut dapat diakses secara komprehensif?","opsi":["Fasilitas pelayanan kesehatan rujukan (Puskesmas rawat inap / RSUD)","Dilakukan sendiri oleh kader posyandu di balai warga tanpa tenaga medis","Cukup dibiarkan sembuh sendiri tanpa intervensi klinis","Ditangani di apotek swasta komersial","Diserahkan ke panti asuhan balita"],"jawabanBenar":0,"pembahasan":"Kasus gizi buruk disertai komplikasi diare kronis dan gangguan tumbuh kembang memerlukan penanganan klinis komprehensif di fasilitas rujukan seperti Puskesmas rawat inap atau RSUD[cite: 1].","pembahasanPilihan":["Kasus gizi buruk disertai komplikasi diare kronis dan gangguan tumbuh kembang memerlukan penanganan klinis komprehensif di fasilitas rujukan seperti Puskesmas rawat inap atau RSUD[cite: 1].","Kader posyandu tidak berwenang menangani kasus klinis gizi buruk berat.","Membiarkan gizi buruk berakibat fatal.","Apotek tidak memiliki fasilitas rawat inap gizi.","Panti asuhan bukan fasilitas medis penanganan gizi buruk."],"version":1},{"id":"kedkom2020-52","soal":"Ayat dalam Al-Qur'an yang menerangkan tentang kewajiban berbuat baik dan berbakti kepada kedua orang tua (salah satunya termuat dalam surah Al-Isra') terdapat pada ayat berapa?","opsi":["Surah Al-Isra' ayat 23-24","Surah Al-Baqarah ayat 1-2","Surah An-Nur ayat 30-31","Surah Al-Ma'idah ayat 3","Surah Luqman ayat 10"],"jawabanBenar":0,"pembahasan":"Perintah utama berbakti kepada orang tua (birrul walidain) secara tegas diabadikan dalam Al-Qur'an Surah Al-Isra' ayat 23-24[cite: 1].","pembahasanPilihan":["Perintah utama berbakti kepada orang tua (birrul walidain) secara tegas diabadikan dalam Al-Qur'an Surah Al-Isra' ayat 23-24[cite: 1].","Al-Baqarah 1-2 berbicara tentang sifat orang bertakwa dan Al-Qur'an.","An-Nur 30-31 mengatur tentang menjaga pandangan.","Al-Ma'idah 3 mengatur tentang makanan yang diharamkan.","Luqman juga memuat nasihat orang tua, namun ayat spesifik yang sering diuji adalah Al-Isra' 23-24."],"version":1},{"id":"kedkom2020-53","soal":"Ny. Z baru melahirkan anak kedua setengah bulan lalu. Karena harus bekerja, ASI Ny. Z sedikit. Seperti anak pertamanya, Ny. Z mengenalkan bayinya pada susu formula sejak usia 2 bulan agar bayi tidak rewel saat ia bekerja. Pola pemberian ASI apakah yang dilakukan jika bayi mendapat ASI diselingi susu formula?","opsi":["Pemberian ASI parsial (Partial breastfeeding)","Pemberian ASI prediksional mutlak","Pemberian ASI eksklusif murni","Pemberian ASI buatan total","Pemberian ASI kolostrum tunggal"],"jawabanBenar":0,"pembahasan":"Pemberian ASI parsial (partial breastfeeding) adalah kondisi di mana bayi mendapatkan kombinasi ASI dan cairan/makanan lain termasuk susu formula[cite: 1].","pembahasanPilihan":["Pemberian ASI parsial (partial breastfeeding) adalah kondisi di mana bayi mendapatkan kombinasi ASI dan cairan/makanan lain termasuk susu formula[cite: 1].","Predominan berarti ASI dengan sedikit air putih, bukan susu formula.","ASI eksklusif berarti bayi hanya menerima ASI tanpa tambahan makanan atau minuman apa pun.","ASI buatan total berarti tidak ada ASI sama sekali.","Kolostrum adalah ASI jaman awal keluar."],"version":1},{"id":"kedkom2020-54","soal":"Seorang kepala puskesmas melakukan evaluasi program dengan metode Lingkaran Pemecahan Masalah (Problem Solving Cycle). Dalam menentukan prioritas, diberikan bobot pada masing-masing kriteria penilaian. Apakah teknik penentuan prioritas masalah tersebut?","opsi":["Metode MCUA (Matrix Criteria Utility Analysis)","Metode Delphi tertutup","Metode PAHO sederhana","Metode Bryant kualitatif","Metode Delbecq kelompok nominal"],"jawabanBenar":0,"pembahasan":"MCUA (Matrix Criteria Utility Analysis) menggunakan pembobotan nilai (skor bobot) pada setiap kriteria penilaian masalah kesehatan[cite: 1].","pembahasanPilihan":["MCUA (Matrix Criteria Utility Analysis) menggunakan pembobotan nilai (skor bobot) pada setiap kriteria penilaian masalah kesehatan[cite: 1].","Delphi menggunakan kuesioner berulang.","PAHO menggunakan kriteria besaran dan kegawatan.","Bryant menggunakan parameter keseriusan dan efektivitas.","Delbecq menggunakan musyawarah tatap muka langsung."],"version":1},{"id":"kedkom2020-55","soal":"Risiko gangguan kesehatan akibat polusi udara yang tinggi bagi warga kota dapat diminimalkan jika kita melakukan upaya untuk menurunkan tingkat apa?","opsi":["Kerentanan (vulnerability) dan paparan risiko (risk exposure)","Kapasitas ketahanan tubuh warga","Jumlah fasilitas kesehatan yang tersedia","Jumlah tenaga medis di rumah sakit","Jumlah obat obatan di apotek"],"jawabanBenar":0,"pembahasan":"Risiko bencana atau gangguan kesehatan lingkungan dapat dikurangi dengan menurunkan tingkat kerentanan masyarakat serta meminimalkan paparan hazard polusi (risk reduction)[cite: 1].","pembahasanPilihan":["Risiko bencana atau gangguan kesehatan lingkungan dapat dikurangi dengan menurunkan tingkat kerentanan masyarakat serta meminimalkan paparan hazard polusi (risk reduction)[cite: 1].","Menurunkan kapasitas justru memperburuk keadaan.","Fasilitas kesehatan harus ditingkatkan, bukan diturunkan.","Jumlah tenaga medis harus ditambah.","Ketersediaan obat harus dijaga."],"version":1},{"id":"kedkom2020-56","soal":"Program kesehatan di puskesmas melakukan pemeriksaan jentik-jentik nyamuk berkala. Indikator jumlah positif jentik nyamuk dalam evaluasi manajemen program termasuk ke dalam jenis indikator apa?","opsi":["Indikator Output (keluaran langsung kegiatan)","Indikator Input (sumber daya awal)","Indikator Outcome (dampak jangka panjang)","Indikator Proses pelaksanaan","Indikator Lingkungan makro"],"jawabanBenar":0,"pembahasan":"Angka jentik atau persentase rumah bebas jentik merupakan hasil langsung (output) dari kegiatan pemberantasan sarang nyamuk yang dilakukan petugas[cite: 1].","pembahasanPilihan":["Angka jentik atau persentase rumah bebas jentik merupakan hasil langsung (output) dari kegiatan pemberantasan sarang nyamuk yang dilakukan petugas[cite: 1].","Input mencakup dana, tenaga, dan alat.","Outcome mencakup penurunan angka kesakitan DBD jangka panjang.","Proses mencakup langkah operasional saat pemeriksaan.","Lingkungan bukan kategori indikator manajemen."],"version":1},{"id":"kedkom2020-57","soal":"Seorang remaja 21 tahun menyelesaikan perguruan tinggi, mengadakan pesta dengan tamu dan pasangan hingga larut malam yang disisipi alkohol serta narkoba, hal tersebut dianggap biasa di lingkungan sosialnya asalkan tidak terjadi kerusuhan terbuka. Menurut Teori Blum, faktor apakah yang paling dominan mempengaruhi perilaku tersebut?","opsi":["Faktor gaya hidup / perilaku (lifestyle & behavior) serta lingkungan sosial","Faktor genetik keturunan keluarga","Faktor ketersediaan fasilitas pelayanan kesehatan modern","Faktor keturunan biologis murni","Faktor pembiayaan jaminan kesehatan nasional"],"jawabanBenar":0,"pembahasan":"Perilaku konsumsi alkohol, narkoba, dan gaya hidup bebas sangat dipengaruhi oleh faktor perilaku (behavior) serta lingkungan sosial budaya sekitar sebagaimana dipetakan dalam Teori H.L. Blum[cite: 1].","pembahasanPilihan":["Perilaku konsumsi alkohol, narkoba, dan gaya hidup bebas sangat dipengaruhi oleh faktor perilaku (behavior) serta lingkungan sosial budaya sekitar sebagaimana dipetakan dalam Teori H.L. Blum[cite: 1].","Penyalahgunaan narkoba bukan faktor genetik mutlak.","Faskes tidak mendorong perilaku konsumsi narkoba.","Faktor biologis tidak menentukan kebiasaan pesta zat terlarang.","JKN tidak berkaitan dengan pilihan gaya hidup negatif."],"version":1},{"id":"kedkom2020-58","soal":"Dokter A mendapatkan laporan jika banyak remaja mengalami keluhan lemah, letih, lesu karena menstruasi, lalu dokter memberikan suplemen zat besi dan melakukan skrining anemia. Upaya pencegahan manakah yang dilakukan oleh dokter tersebut?","opsi":["Early diagnosis and prompt treatment (Diagnosis dini dan pengobatan segera)","Health promotion murni","Specific protection vaksinasi","Rehabilitation sosial","Paliatif terminal"],"jawabanBenar":0,"pembahasan":"Melakukan skrining untuk mendeteksi anemia secara dini serta memberikan terapi zat besi segera pada kelompok berisiko termasuk dalam Early diagnosis and prompt treatment (pencegahan sekunder)[cite: 1].","pembahasanPilihan":["Melakukan skrining untuk mendeteksi anemia secara dini serta memberikan terapi zat besi segera pada kelompok berisiko termasuk dalam Early diagnosis and prompt treatment (pencegahan sekunder)[cite: 1].","Health promotion bersifat edukasi umum tanpa deteksi dini khusus.","Specific protection contohnya imunisasi.","Rehabilitasi memulihkan kecacatan.","Paliatif merawat pasien menjelang akhir hayat."],"version":1},{"id":"kedkom2020-59","soal":"Dokter layanan primer dalam sistem JKN menerima pembayaran dengan metode kapitasi. Apakah arti dari sistem pembayaran kapitasi tersebut?","opsi":["Fasilitas kesehatan dibayar di muka secara tetap per bulan berdasarkan jumlah peserta terdaftar, terlepas dari apakah peserta berobat atau tidak","Dokter dibayar tunai setiap kali selesai memeriksa pasien","Dokter dibayar berdasarkan durasi jam kerja di klinik","Dokter tidak mendapat bayaran sama sekali dari BPJS","Pembayaran dilakukan hanya jika pasien dioperasi besar"],"jawabanBenar":0,"pembahasan":"Kapitasi adalah metode pembayaran di muka (pre-payment) kepada fasilitas kesehatan tingkat pertama berdasarkan jumlah peserta yang terdaftar di faskes tersebut setiap bulannya[cite: 1].","pembahasanPilihan":["Kapitasi adalah metode pembayaran di muka (pre-payment) kepada fasilitas kesehatan tingkat pertama berdasarkan jumlah peserta yang terdaftar di faskes tersebut setiap bulannya[cite: 1].","Bayaran periksa per tindakan adalah fee-for-service.","Pembayaran berdasarkan jam adalah time-based.","Dokter menerima dana kapitasi sesuai ketentuan BPJS.","Operasi besar diatur dengan sistem INA-CBG di rumah sakit."],"version":1},{"id":"kedkom2020-60","soal":"Surilans mengenai indikator kesehatan individual dan masyarakat sebelum menentukan diagnosis klinis massal bertujuan untuk deteksi dini. Apakah nama jenis surveilans tersebut?","opsi":["Surveilans kesehatan masyarakat (Public health surveillance)","Surveilans bedah ortopedi","Surveilans klinik privat","Surveilans logistik obat","Surveilans keuangan instansi"],"jawabanBenar":0,"pembahasan":"Surveilans kesehatan masyarakat adalah pengumpulan, analisis, dan interpretasi data kesehatan secara terus menerus untuk perencanaan dan evaluasi tindakan kesehatan publik[cite: 1].","pembahasanPilihan":["Surveilans kesehatan masyarakat adalah pengumpulan, analisis, dan interpretasi data kesehatan secara terus menerus untuk perencanaan dan evaluasi tindakan kesehatan publik[cite: 1].","Surveilans ortopedi bukan istilah standar epidemiologi.","Surveilans klinik privat tidak mencakup skala populasi luas.","Logistik obat ranah manajemen farmasi.","Keuangan ranah akuntansi."],"version":1},{"id":"kedkom2020-61","soal":"Program promosi kesehatan di puskesmas menyelenggarakan penyuluhan pemberantasan sarang nyamuk. Indikator 'Angka Bebas Jentik' (ABJ) merupakan ukuran keberhasilan apa bagi program tersebut?","opsi":["Indikator Output (keluaran program promkes)","Indikator Input pendanaan","Indikator Outcome derajat kesehatan jangka panjang","Indikator Lingkungan fisik semata","Indikator Proses administrasi"],"jawabanBenar":0,"pembahasan":"Angka Bebas Jentik (ABJ) merupakan indikator keluaran (output) langsung dari intervensi promosi kesehatan dan pemberantasan sarang nyamuk di lingkungan warga[cite: 1].","pembahasanPilihan":["Angka Bebas Jentik (ABJ) merupakan indikator keluaran (output) langsung dari intervensi promosi kesehatan dan pemberantasan sarang nyamuk di lingkungan warga[cite: 1].","Input mencakup anggaran dan tenaga.","Outcome mencakup penurunan insidens kasus DBD di wilayah tersebut.","Lingkungan bukan jenis indikator manajerial.","Proses mencakup jalannya kegiatan penyuluhan."],"version":1},{"id":"kedkom2020-62","soal":"Seorang anak usia 2 tahun 1 bulan, BB 8.5 kg, TB 70 cm, keluhan mencret 1 bulan, hanya minum ASI, mengalami gangguan perkembangan dan gizi kurang/buruk. Orang tua pemulung dengan 5 anak kecil. Di manakah tatalaksana rujukan medis utama yang tepat bagi anak tersebut?","opsi":["Fasilitas pelayanan kesehatan rujukan (Puskesmas perawatan / Rumah Sakit Umum Daerah)","Praktik dokter spesialis kulit swasta","Kader PKK kelurahan tanpa pengawasan medis","Dibiarkan di rumah hingga sembuh sendiri","Diserahkan ke balai pengobatan hewan"],"jawabanBenar":0,"pembahasan":"Anak dengan gizi buruk dan komplikasi kronis harus ditangani secara medis di fasilitas rujukan seperti Puskesmas rawat inap atau RSUD[cite: 1].","pembahasanPilihan":["Anak dengan gizi buruk dan komplikasi kronis harus ditangani secara medis di fasilitas rujukan seperti Puskesmas rawat inap atau RSUD[cite: 1].","Dokter kulit tidak menangani gizi buruk anak.","Kader PKK tidak memiliki kompetensi klinis terapi gizi buruk.","Membiarkan anak gizi buruk berisiko kematian.","Pengobatan hewan tidak relevan."],"version":1},{"id":"kedkom2020-63","soal":"Puskesmas mengalami kenaikan kasus HIV/AIDS sebesar 50% dari tahun sebelumnya, tetapi tidak sebanding dengan peningkatan ARV yang hanya 10%. Hal itu disebabkan karena kasus HIV/AIDS yang loss to follow up. Apakah hambatan psikososial terbesar yang sering dialami pasien dalam konseling kelompok?","opsi":["Tingginya stigma sosial, diskriminasi, dan ketakutan status terbuka di masyarakat","Ketersediaan fasilitas internet gratis di puskesmas","Terlalu banyaknya tenaga dokter spesialis mata","Mahalnya harga kertas resep dokter","Kurangnya lampu penerangan jalan umum"],"jawabanBenar":0,"pembahasan":"Hambatan utama pasien HIV dalam mengikuti konseling kelompok dan berobat teratur adalah tingginya stigma negatif, diskriminasi sosial, serta ketakutan identitas mereka diketahui publik[cite: 1].","pembahasanPilihan":["Hambatan utama pasien HIV dalam mengikuti konseling kelompok dan berobat teratur adalah tingginya stigma negatif, diskriminasi sosial, serta ketakutan identitas mereka diketahui publik[cite: 1].","Internet tidak berkaitan dengan hambatan psikososial HIV.","Spesialis mata tidak berhubungan dengan kasus HIV.","Kertas resep tidak mempengaruhi kepatuhan ODHA.","Lampu jalan tidak berhubungan langsung dengan konseling."],"version":1},{"id":"kedkom2020-64","soal":"Air bersih yang digunakan untuk kebutuhan sehari-hari mempunyai syarat antara lain tidak terkontaminasi mikroorganisme patogen seperti Escherichia coli. Termasuk ke dalam kategori syarat apakah parameter tersebut?","opsi":["Syarat mikrobiologis / bakteriologis","Syarat kimiawi logam berat","Syarat fisik kejernihan air","Syarat radioaktif nuklir","Syarat ekonomis komersial"],"jawabanBenar":0,"pembahasan":"Keberadaan bakteri Escherichia coli sebagai indikator pencemaran tinja di dalam air bersih termasuk dalam parameter persyaratan mikrobiologis / bakteriologis[cite: 1].","pembahasanPilihan":["Keberadaan bakteri Escherichia coli sebagai indikator pencemaran tinja di dalam air bersih termasuk dalam parameter persyaratan mikrobiologis / bakteriologis[cite: 1].","Kimiawi mencakup pH, logam, dan zat terlarut.","Fisik mencakup warna, bau, rasa, dan kekeruhan.","Radioaktif mencakup unsur pancaran radiasi.","Ekonomis bukan parameter kualitas air sehat."],"version":1},{"id":"kedkom2020-65","soal":"Dalam metode penentuan prioritas masalah kesehatan menggunakan metode Bryant, indikator apakah yang digunakan untuk menilai seberapa besar tingkat keparahan, kesakitan, dan kematian yang ditimbulkan?","opsi":["Seriousness / tingkat keseriusan masalah","Magnitude jumlah penduduk terkena","Emergency kedaruratan waktu","Affordability pembiayaan","Simplicity kemudahan teknis"],"jawabanBenar":0,"pembahasan":"Dalam metode Bryant, kriteria 'Seriousness' digunakan untuk menilai tingkat kegawatan, keparahan penyakit, morbiditas, serta mortalitas yang ditimbulkan oleh suatu masalah kesehatan[cite: 1].","pembahasanPilihan":["Dalam metode Bryant, kriteria 'Seriousness' digunakan untuk menilai tingkat kegawatan, keparahan penyakit, morbiditas, serta mortalitas yang ditimbulkan oleh suatu masalah kesehatan[cite: 1].","Magnitude menilai besar kecilnya persentase populasi yang terkena.","Emergency menilai kedaruratan mendesak.","Affordability menilai kemudahan pembiayaan.","Simplicity menilai kesederhanaan."],"version":1},{"id":"kedkom2020-66","soal":"Pandemi Covid-19 sudah berakhir. Masyarakat kembali menata kehidupannya baik di bidang kesehatan maupun perekonomian. Kondisi ini dalam siklus manajemen bencana termasuk ke dalam fase apa?","opsi":["Fase Pascakrisis / pemulihan (recovery)","Fase Tanggap darurat akut","Fase Kesiapsiagaan siaga","Fase Mitigasi pencegahan","Fase Impact hantaman"],"jawabanBenar":0,"pembahasan":"Fase pascakrisis adalah tahapan ketika situasi darurat telah selesai dan masyarakat melakukan rehabilitasi serta rekonstruksi kehidupan ekonomi dan sosial kesehatan[cite: 1].","pembahasanPilihan":["Fase pascakrisis adalah tahapan ketika situasi darurat telah selesai dan masyarakat melakukan rehabilitasi serta rekonstruksi kehidupan ekonomi dan sosial kesehatan[cite: 1].","Tanggap darurat adalah saat bencana sedang terjadi.","Kesiapsiagaan sebelum bencana.","Mitigasi jauh sebelum bencana.","Impact saat kejadian."],"version":1},{"id":"kedkom2020-67","soal":"Bagaimanakah hukum menjaga kesehatan dalam pandangan syariat Islam secara umum bagi setiap mukallaf?","opsi":["Wajib 'ain","Sunnah muakkadah","Mubah mutlak","Makruh tahrim","Haram qath'i"],"jawabanBenar":0,"pembahasan":"Menjaga kesehatan jiwa dan raga hukumnya wajib 'ain demi kelangsungan hidup dan pelaksanaan kewajiban beribadah kepada Allah SWT[cite: 1].","pembahasanPilihan":["Menjaga kesehatan jiwa dan raga hukumnya wajib 'ain demi kelangsungan hidup dan pelaksanaan kewajiban beribadah kepada Allah SWT[cite: 1].","Derajatnya lebih tinggi dari sunnah muakkadah.","Mubah berarti boleh, tidak sesuai dengan konsep penjagaan jiwa.","Makruh adalah perbuatan yang dibenci.","Haram adalah larangan mutlak."],"version":1},{"id":"kedkom2020-68","soal":"Menurut ulama kontemporer, pembolehan dan bahkan kewajiban melakukan tindakan medis seperti transfusi darah didasarkan pada tujuan syariat Islam untuk menyelamatkan nyawa manusia dari kematian. Hal ini lazim disebut sebagai prinsip apa?","opsi":["Hifz nafs (Memelihara jiwa)","Hifz nasab (Memelihara keturunan)","Hifz din (Memelihara agama)","Hifz aql (Memelihara akal)","Hifz mal (Memelihara harta)"],"jawabanBenar":0,"pembahasan":"Prinsip pemeliharaan dan perlindungan nyawa manusia dari kematian dikategorikan sebagai Hifz nafs dalam maqashid syariah[cite: 1].","pembahasanPilihan":["Prinsip pemeliharaan dan perlindungan nyawa manusia dari kematian dikategorikan sebagai Hifz nafs dalam maqashid syariah[cite: 1].","Hifz nasab berkaitan dengan keturunan.","Hifz din berkaitan dengan agama.","Hifz aql berkaitan dengan akal.","Hifz mal berkaitan dengan harta."],"version":1},{"id":"kedkom2020-69","soal":"Terdapat kenaikan kasus HIV/AIDS sebesar 50% di suatu kecamatan, namun tidak sejalan dengan kenaikan penggunaan ARV yang hanya 10% karena tingginya kasus loss to follow up. Konseling apakah yang paling tepat disarankan untuk mengatasi masalah kepatuhan dan dukungan kelompok tersebut?","opsi":["Konseling kelompok dukungan (Support group counseling / peer support)","Konseling hukum pidana korporasi","Konseling arisan keluarga besar","Konseling teknik mesin industri","Konseling tata boga komersial"],"jawabanBenar":0,"pembahasan":"Konseling kelompok dukungan (support group) sangat efektif bagi pasien HIV untuk berbagi pengalaman, mengurangi rasa terisolasi, serta meningkatkan kepatuhan minum obat ARV[cite: 1].","pembahasanPilihan":["Konseling kelompok dukungan (support group) sangat efektif bagi pasien HIV untuk berbagi pengalaman, mengurangi rasa terisolasi, serta meningkatkan kepatuhan minum obat ARV[cite: 1].","Hukum pidana tidak relevan dengan penanganan klinis pasien.","Arisan keluarga tidak membahas kepatuhan medis.","Teknik mesin tidak berhubungan dengan kesehatan.","Tata boga untuk kuliner."],"version":1},{"id":"kedkom2020-70","soal":"Seorang anak laki-laki usia 14 tahun datang dengan multipel fraktur akibat kecelakaan menabrak lampu merah dalam pengaruh alkohol. Ayahnya berkata anaknya pergi karena marah dilarang merayakan tahun baru di Puncak. Di bawah ini, manakah yang tidak termasuk ke dalam karakteristik umum masalah sosial?","opsi":["Merupakan kondisi yang selalu disepakati bermanfaat secara positif oleh seluruh warga masyarakat tanpa terkecuali","Menimbulkan keresahan bagi sebagian besar masyarakat","Berkembang dari kondisi perilaku dan interaksi sosial menyimpang","Memerlukan penanganan kolektif dari institusi sosial","Berkaitan dengan norma yang dilanggar"],"jawabanBenar":0,"pembahasan":"Masalah sosial pada hakikatnya adalah kondisi yang dinilai merugikan, meresahkan, atau menyimpang oleh masyarakat, sehingga pernyataan bahwa masalah sosial selalu disepakati bermanfaat adalah keliru[cite: 1].","pembahasanPilihan":["Masalah sosial pada hakikatnya adalah kondisi yang dinilai merugikan, meresahkan, atau menyimpang oleh masyarakat, sehingga pernyataan bahwa masalah sosial selalu disepakati bermanfaat adalah keliru[cite: 1].","Merugikan/meresahkan masyarakat adalah ciri masalah sosial.","Bersumber dari penyimpangan perilaku.","Memerlukan penanganan bersama.","Melanggar norma sosial."],"version":1},{"id":"kedkom2020-71","soal":"Indonesia merupakan negara dengan angka pernikahan usia dini yang tinggi. Faktor utama apakah yang seringkali menjadi pemicu di balik tingginya fenomena tersebut?","opsi":["Kehamilan di luar nikah / kehamilan remaja dan faktor norma sosial ekonomi","Kewajiban menempuh pendidikan strata tiga doktor","Ketersediaan lapangan kerja khusus anak di bawah umur","Larangan mutlak menikah bagi orang dewasa","Kewajiban memiliki paspor internasional"],"jawabanBenar":0,"pembahasan":"Faktor pemicu utama perkawinan anak di antaranya adalah kehamilan yang tidak diinginkan di kalangan remaja (hamil di luar nikah), tingkat pendidikan, serta kondisi ekonomi keluarga[cite: 1].","pembahasanPilihan":["Faktor pemicu utama perkawinan anak di antaranya adalah kehamilan yang tidak diinginkan di kalangan remaja (hamil di luar nikah), tingkat pendidikan, serta kondisi ekonomi keluarga[cite: 1].","Pendidikan tinggi justru menunda usia nikah.","Undang-undang melarang pekerja anak.","Orang dewasa dibolehkan menikah secara sah.","Paspor tidak ada kaitannya dengan pernikahan dini."],"version":1},{"id":"kedkom2020-72","soal":"Survei kesehatan nasional yang secara berkala mengukur berbagai indikator pembangunan kesehatan termasuk target MDGs di tingkat provinsi dan nasional adalah:","opsi":["Riskesdas (Riset Kesehatan Dasar) / Susenas","Sensus pertambangan batu bara","Survei lalu lintas udara komersial","Sensus kendaraan bermotor kota","Survei properti perumahan mewah"],"jawabanBenar":0,"pembahasan":"Riskesdas dan Susenas adalah survei nasional utama yang memotret indikator kesehatan, demografi, dan kesejahteraan sosial di tingkat provinsi hingga nasional[cite: 1].","pembahasanPilihan":["Riskesdas dan Susenas adalah survei nasional utama yang memotret indikator kesehatan, demografi, dan kesejahteraan sosial di tingkat provinsi hingga nasional[cite: 1].","Pertambangan diatur ESDM.","Lalu lintas udara diatur perhubungan udara.","Kendaraan bermotor diatur kepolisian/dinas perhubungan.","Properti diatur agraria."],"version":1},{"id":"kedkom2020-73","soal":"Seorang kepala puskesmas mengumpulkan seluruh staf puskesmas termasuk dokter dan bidan dalam rangka menentukan prioritas masalah kesehatan menggunakan metode musyawarah kelompok nominal tatap muka. Apakah nama metode tersebut?","opsi":["Metode Delbecq (Nominal Group Technique)","Metode Hanlon matematis murni","Metode Delphi jarak jauh tanpa tatap muka","Metode Bryant persentase tunggal","Metode kuesioner pos"],"jawabanBenar":0,"pembahasan":"Metode Delbecq mempertemukan para ahli atau staf dalam diskusi terstruktur tatap muka untuk menetapkan peringkat prioritas masalah secara objektif[cite: 1].","pembahasanPilihan":["Metode Delbecq mempertemukan para ahli atau staf dalam diskusi terstruktur tatap muka untuk menetapkan peringkat prioritas masalah secara objektif[cite: 1].","Hanlon menggunakan perhitungan matematis skor numerik.","Delphi tidak mempertemukan peserta secara langsung.","Bryant menggunakan matriks kegawatan.","Kuesioner pos adalah instrumen pengumpulan data."],"version":1},{"id":"kedkom2020-74","soal":"Berdasarkan evaluasi P2M Puskesmas didapatkan peningkatan kasus HIV/AIDS 50% yang tidak sejalan dengan akses ARV karena pasien loss to follow up, lalu diusulkan konseling kelompok. Apakah hambatan psikososial utama yang sering dihadapi dalam pelaksanaan konseling tersebut?","opsi":["Tingginya stigma dan diskriminasi di masyarakat serta ketakutan terbuka status HIV","Ketiadaan gedung puskesmas sama sekali di suatu wilayah","Kewajiban membayar pajak penghasilan tinggi","Larangan pemerintah melakukan pertemuan kelompok","Ketersediaan obat ARV yang berlimpah ruah di rumah warga"],"jawabanBenar":0,"pembahasan":"Stigma sosial yang kuat, diskriminasi, dan rasa malu atau takut identitasnya diketahui orang lain menjadi hambatan utama ODHA untuk hadir dalam konseling kelompok[cite: 1].","pembahasanPilihan":["Stigma sosial yang kuat, diskriminasi, dan rasa malu atau takut identitasnya diketahui orang lain menjadi hambatan utama ODHA untuk hadir dalam konseling kelompok[cite: 1].","Gedung puskesmas tersedia secara fisik.","Pajak tidak berhubungan dengan konseling HIV.","Pemerintah mendukung edukasi kesehatan.","ARV yang banyak justru hal positif, bukan hambatan."],"version":1},{"id":"kedkom2020-75","soal":"Manakah di bawah ini yang termasuk ke dalam kelompok imunisasi dasar lengkap pada anak di Indonesia sesuai program kementerian kesehatan?","opsi":["BCG, Polio, DPT-HB-Hib, dan Campak / Rubella","Hanya vaksin rabies tahunan","Hanya vaksin demam berdarah dewasa","Vaksin kanker serviks khusus lansia","Vaksin malaria tropika"],"jawabanBenar":0,"pembahasan":"Imunisasi dasar lengkap bagi bayi di Indonesia meliputi BCG, Polio tetes/suntik, DPT-HB-Hib, dan Campak/Rubella sesuai jadwal Kemenkes[cite: 1].","pembahasanPilihan":["Imunisasi dasar lengkap bagi bayi di Indonesia meliputi BCG, Polio tetes/suntik, DPT-HB-Hib, dan Campak/Rubella sesuai jadwal Kemenkes[cite: 1].","Rabies diberikan atas indikasi gigitan hewan penular.","Vaksin DBD bukan bagian dari imunisasi dasar wajib universal nasional untuk bayi.","HPV untuk remaja putri.","Malaria diberikan di wilayah endemis tertentu."],"version":1},{"id":"kedkom2020-76","soal":"Soal mengenai kesehatan gizi kurang dan gizi lebih, manakah pernyataan yang SALAH mengenai kondisi stunting pada anak?","opsi":["Stunting saat dewasa secara otomatis pasti selalu menjadi obesitas parah tanpa kecuali","Stunting adalah kondisi gagal tumbuh pada anak balita akibat kekurangan gizi kronis","Stunting berdampak pada keterlambatan perkembangan kognitif anak","Stunting dapat dicegah melalui perbaikan gizi 1000 HPK","Anak stunting memiliki tinggi badan di bawah standar usianya"],"jawabanBenar":0,"pembahasan":"Pernyataan bahwa anak stunting saat dewasa pasti otomatis menjadi obesitas adalah keliru; meskipun ada korelasi risiko metabolik (double burden), hal tersebut tidak mutlak terjadi pada setiap individu[cite: 1].","pembahasanPilihan":["Pernyataan bahwa anak stunting saat dewasa pasti otomatis menjadi obesitas adalah keliru; meskipun ada korelasi risiko metabolik (double burden), hal tersebut tidak mutlak terjadi pada setiap individu[cite: 1].","Stunting adalah gagal tumbuh akibat gizi kronis (pernyataan benar).","Berpengaruh pada kognitif (pernyataan benar).","Dicegah lewat 1000 HPK (pernyataan benar).","Tinggi badan di bawah standar (pernyataan benar)."],"version":1},{"id":"kedkom2020-77","soal":"Saat mengevaluasi KIA, petugas puskesmas telah menentukan bahwa dengan mengintervensi akar masalah berupa kurangnya koordinasi antar petugas, maka masalah akan terselesaikan. Langkah apakah yang sedang dilakukan petugas dalam menerapkan metode Lingkaran Pemecahan Masalah?","opsi":["Menetapkan penyebab masalah yang paling dominan / akar penyebab masalah","Membuat laporan keuangan triwulan","Membubarkan struktur organisasi puskesmas","Mengganti seluruh pasien rawat inap","Menutup fasilitas pelayanan darurat"],"jawabanBenar":0,"pembahasan":"Menemukan akar masalah atau penyebab dominan (seperti kurangnya koordinasi) merupakan tahapan krusial dalam analisis lingkaran pemecahan masalah (problem solving cycle) sebelum merumuskan intervensi[cite: 1].","pembahasanPilihan":["Menemukan akar masalah atau penyebab dominan (seperti kurangnya koordinasi) merupakan tahapan krusial dalam analisis lingkaran pemecahan masalah (problem solving cycle) sebelum merumuskan intervensi[cite: 1].","Laporan keuangan bukan langkah pemecahan masalah program KIA.","Membubarkan organisasi adalah tindakan destruktif.","Mengganti pasien tidak relevan.","Menutup IGD melanggar fungsi faskes."],"version":1},{"id":"kedkom2020-78","soal":"Di Indonesia tingkat pernikahan usia dini sangat tinggi. Kesimpulan manakah yang paling tepat dapat ditarik dari kondisi tersebut?","opsi":["Program kesehatan reproduksi remaja (KRR) belum tersosialisasi secara merata dan efektif","Masyarakat sudah sangat makmur secara ekonomi","Angka harapan hidup lansia meningkat tajam","Seluruh remaja di Indonesia telah menempuh pendidikan S2","Angka kematian ibu melahirkan sudah mencapai nol"],"jawabanBenar":0,"pembahasan":"Tingginya pernikahan dini mencerminkan masih kurang optimalnya sosialisasi program Kesehatan Reproduksi Remaja (KRR) serta edukasi di tengah masyarakat[cite: 1].","pembahasanPilihan":["Tingginya pernikahan dini mencerminkan masih kurang optimalnya sosialisasi program Kesehatan Reproduksi Remaja (KRR) serta edukasi di tengah masyarakat[cite: 1].","Pernikahan dini justru sering berkorelasi dengan kemiskinan.","Tidak berhubungan langsung dengan harapan hidup lansia.","Sebagian besar pelaku pernikahan dini berpendidikan rendah.","AKI di Indonesia masih menjadi tantangan besar."],"version":1},{"id":"kedkom2020-79","soal":"Karena di daerah tujuan ibadah (seperti tanah suci umroh/haji) cuaca sangat panas terik, saran pencegahan apakah yang paling tepat diberikan oleh dokter kepada Jemaah?","opsi":["Membawa botol minum untuk hidrasi teratur dan menggunakan payung / penutup kepala","Memakai jaket musim dingin berlapis tiga","Berjemur di bawah matahari langsung tanpa pelindung","Tidak minum air sama sekali selama beribadah","Berjalan kaki tanpa alas kaki di atas pasir panas"],"jawabanBenar":0,"pembahasan":"Antisipasi cuaca panas ekstrem di tanah suci menuntut jemaah untuk menjaga hidrasi (membawa botol minum) serta melindungi diri dari sengatan matahari langsung (menggunakan payung/penutup kepala)[cite: 1].","pembahasanPilihan":["Antisipasi cuaca panas ekstrem di tanah suci menuntut jemaah untuk menjaga hidrasi (membawa botol minum) serta melindungi diri dari sengatan matahari langsung (menggunakan payung/penutup kepala)[cite: 1].","Jaket musim dingin memicu heat stroke.","Berjemur tanpa pelindung berbahaya bagi kulit dan cairan tubuh.","Tidak minum air memicu dehidrasi berat.","Tanpa alas kaki berbahaya bagi telapak kaki."],"version":1},{"id":"kedkom2020-80","soal":"Pemerintah Indonesia melalui Kementerian Kesehatan mengupayakan program pencegahan penyakit melalui imunisasi dasar lengkap. Apa saja yang termasuk dalam kelompok imunisasi dasar wajib bagi bayi?","opsi":["Polio, BCG, DPT-HB-Hib, dan Campak","Hanya vaksin rabies hewan","Hanya vaksin influenza musiman dewasa","Vaksin kanker serviks usia lanjut","Vaksin malaria khusus pelancong"],"jawabanBenar":0,"pembahasan":"Imunisasi dasar wajib bagi bayi di Indonesia mencakup vaksin Polio, BCG, DPT-HB-Hib, dan Campak[cite: 1].","pembahasanPilihan":["Imunisasi dasar wajib bagi bayi di Indonesia mencakup vaksin Polio, BCG, DPT-HB-Hib, dan Campak[cite: 1].","Rabies diberikan atas indikasi gigitan hewan.","Influenza bukan imunisasi dasar wajib bayi nasional.","HPV untuk remaja putri.","Malaria untuk wilayah endemis khusus."],"version":1},{"id":"kedkom2020-81","soal":"Pada masa pandemi Covid-19 banyak menimbulkan krisis kematian, namun saat ini setelah pandemi berakhir, masyarakat mulai melakukan pemulihan pembangunan ekonomi. Apakah istilah fase manajemen yang sedang berlangsung?","opsi":["Fase Transisi darurat menuju pemulihan / pascakrisis","Fase Siaga darurat bencana aktif","Fase Mitigasi struktural awal","Fase Tanggap darurat hantaman","Fase Evakuasi massal"],"jawabanBenar":0,"pembahasan":"Masa transisi menuju pemulihan pascakrisis adalah tahapan saat ancaman darurat mereda dan aktivitas sosial ekonomi dibangun kembali[cite: 1].","pembahasanPilihan":["Masa transisi menuju pemulihan pascakrisis adalah tahapan saat ancaman darurat mereda dan aktivitas sosial ekonomi dibangun kembali[cite: 1].","Siaga darurat adalah saat ancaman di depan mata.","Mitigasi sebelum bencana.","Tanggap darurat saat kejadian.","Evakuasi saat penyelamatan awal."],"version":1},{"id":"kedkom2020-82","soal":"Seorang ibu memiliki dua anak, ASI sedikit, harus bekerja penuh waktu, dan anak pertama dulu diberikan susu formula sejak usia 2 bulan, begitu pula anak keduanya. Bagaimana cara agar anak kedua tetap bisa mendapatkan hak ASI secara optimal di tengah kesibukan kerja ibu?","opsi":["Memerah ASI (pumping) di tempat kerja dan menyimpannya untuk diberikan kepada bayi saat ibu di rumah","Menghentikan total produksi ASI dan beralih permanen ke susu sapi segar","Memberikan makanan padat nasi tim sejak usia 1 minggu","Membawa bayi bekerja ke pabrik kimia berbahaya","Meminta anak tertua menyusui adiknya"],"jawabanBenar":0,"pembahasan":"Solusi terbaik bagi ibu bekerja agar anak tetap mendapat ASI adalah melakukan manajemen laktasi berupa memerah ASI (expressing breastmilk) saat bekerja dan memberikannya saat kembali ke rumah[cite: 1].","pembahasanPilihan":["Solusi terbaik bagi ibu bekerja agar anak tetap mendapat ASI adalah melakukan manajemen laktasi berupa memerah ASI (expressing breastmilk) saat bekerja dan memberikannya saat kembali ke rumah[cite: 1].","Menghentikan total ASI bertentangan dengan upaya peningkatan gizi bayi.","Nasi tim usia 1 minggu melanggar prinsip ASI eksklusif 6 bulan.","Membawa bayi ke pabrik kimia membahayakan kesehatannya.","Anak tertua tidak dapat memproduksi ASI."],"version":1},{"id":"kedkom2020-83","soal":"Di Puskesmas Kemayoran terdapat peningkatan kasus HIV/AIDS 50% sementara akses ARV 10% akibat loss to follow up. Puskesmas menyarankan konseling kelompok. Apa upaya strategis puskesmas untuk mengurangi hambatan keikutsertaan dalam konseling kelompok tersebut?","opsi":["Menyediakan layanan dukungan sebaya (peer support) dan menjaga kerahasiaan ketat","Memasang foto seluruh pasien HIV di baliho jalan raya","Mewajibkan pasien membayar denda jutaan rupiah","Menutup layanan poli HIV secara permanen","Melaporkan seluruh pasien ke lembaga penegak hukum"],"jawabanBenar":0,"pembahasan":"Penyediaan layanan dukungan sebaya (peer support) serta jaminan kerahasiaan medis yang baik terbukti efektif meredakan ketakutan dan hambatan psikososial ODHA untuk hadir[cite: 1].","pembahasanPilihan":["Penyediaan layanan dukungan sebaya (peer support) serta jaminan kerahasiaan medis yang baik terbukti efektif meredakan ketakutan dan hambatan psikososial ODHA untuk hadir[cite: 1].","Memasang foto melanggar hukum privasi dan etik kedokteran.","Denda memberatkan pasien miskin.","Menutup poli justru memperparah wabah.","Melaporkan ke penegak hukum melanggar kerahasiaan medis pasien."],"version":1},{"id":"kedkom2020-84","soal":"Keluarga inti yang harmonis berdampak pada kehidupan sosial keluarga, sehingga mendukung kesehatan anggotanya. Sebaliknya, keluarga disfungsional menimbulkan stres dan konflik. Termasuk ke dalam aspek budaya apakah institusi keluarga tersebut?","opsi":["Struktur sosial (Lembaga dan organisasi kemasyarakatan)","Infrastruktur modal ekonomi","Suprastruktur keyakinan abstrak","Multistruktur internasional","Sub-kultur artifisial"],"jawabanBenar":0,"pembahasan":"Keluarga sebagai unit institusi sosial terkecil diklasifikasikan ke dalam aspek struktur sosial masyarakat[cite: 1].","pembahasanPilihan":["Keluarga sebagai unit institusi sosial terkecil diklasifikasikan ke dalam aspek struktur sosial masyarakat[cite: 1].","Infrastruktur berkaitan dengan ekonomi produksi.","Suprastruktur berkaitan dengan nilai ideologi.","Multistruktur bukan istilah baku.","Sub-kultur kelompok kecil."],"version":1},{"id":"kedkom2020-85","soal":"Riset kesehatan nasional berbasis komunitas yang melakukan integrasi data dengan Survei Sosial Ekonomi Nasional (Susenas) secara berkala dikenal sebagai:","opsi":["Riskesdas (Riset Kesehatan Dasar)","Sensus pabrik baja","Survei lalu lintas tol","Sensus peternakan unggas","Survei pariwisata asing"],"jawabanBenar":0,"pembahasan":"Riset Kesehatan Dasar (Riskesdas) seringkali diintegrasikan dengan kerangka sampel Susenas Badan Pusat Statistik (BPS) untuk menghasilkan data kesehatan dan sosio-ekonomi yang valid[cite: 1].","pembahasanPilihan":["Riset Kesehatan Dasar (Riskesdas) seringkali diintegrasikan dengan kerangka sampel Susenas Badan Pusat Statistik (BPS) untuk menghasilkan data kesehatan dan sosio-ekonomi yang valid[cite: 1].","Pabrik baja diurus kementerian perindustrian.","Lalu lintas tol diurus Jasa Marga.","Peternakan diurus kementerian pertanian.","Pariwisata diurus kementerian pariwisata."],"version":1},{"id":"kedkom2020-86","soal":"Narasi tentang Ny. Z yang baru melahirkan anak kedua dan kesulitan mengeluarkan ASI sehingga ingin memberikan susu formula agar bayi tidak rewel saat ditinggal bekerja. Termasuk ke dalam pola pemberian ASI apakah kondisi tersebut?","opsi":["Pemberian ASI parsial (Partial breastfeeding)","Pemberian ASI eksklusif mutlak","Pemberian ASI prediksional air putih","Pemberian kolostrum murni","Pemberian cairan infus parenteral"],"jawabanBenar":0,"pembahasan":"Kombinasi antara pemberian ASI dan susu formula dikategorikan sebagai pola pemberian ASI parsial[cite: 1].","pembahasanPilihan":["Kombinasi antara pemberian ASI dan susu formula dikategorikan sebagai pola pemberian ASI parsial[cite: 1].","ASI eksklusif tidak boleh dicampur susu formula.","Predominan mencakup air putih, bukan susu formula.","Kolostrum adalah ASI hari pertama.","Infus bukan metode menyusui."],"version":1},{"id":"kedkom2020-87","soal":"Kegiatan riset kesehatan nasional yang dirancang khusus untuk mengevaluasi target pembangunan milenium (MDG's) di bidang kesehatan adalah:","opsi":["Riskesdas 2013","Susenas umum kor","Survei industri manufaktur","Sensus perdagangan sandang","Survei transportasi laut"],"jawabanBenar":0,"pembahasan":"Riskesdas 2013 merupakan riset kesehatan utama yang mengevaluasi pencapaian target MDG's kesehatan nasional[cite: 1].","pembahasanPilihan":["Riskesdas 2013 merupakan riset kesehatan utama yang mengevaluasi pencapaian target MDG's kesehatan nasional[cite: 1].","Susenas berfokus pada sosio-ekonomi makro.","Manufaktur diurus perindustrian.","Perdagangan diurus perdagangan.","Transportasi laut diurus perhubungan."],"version":1},{"id":"kedkom2020-88","soal":"Puskesmas ingin menentukan prioritas masalah dengan melakukan skoring menurut kriteria pembobotan tertentu. Teknik metode apakah yang paling tepat digunakan?","opsi":["Metode MCUA (Matrix Criteria Utility Analysis)","Metode Delphi tertutup","Metode Delbecq tanpa skor","Metode Bryant kualitatif murni","Metode observasi acak"],"jawabanBenar":0,"pembahasan":"Metode MCUA menggunakan matriks kriteria dengan pembobotan nilai angka untuk menentukan peringkat prioritas masalah secara objektif[cite: 1].","pembahasanPilihan":["Metode MCUA menggunakan matriks kriteria dengan pembobotan nilai angka untuk menentukan peringkat prioritas masalah secara objektif[cite: 1].","Delphi menggunakan kuisioner berulang.","Delbecq adalah diskusi kelompok nominal.","Bryant menggunakan parameter kegawatan.","Observasi adalah pengumpulan data."],"version":1},{"id":"kedkom2020-89","soal":"Ny. Z melahirkan anak kedua, harus bekerja dan bayinya harus ditinggal serta diberi susu formula sejak usia 2 bulan. Bagaimanakah agar Ny. Z tetap dapat memberikan manfaat ASI yang baik bagi bayinya di sela kesibukan bekerja?","opsi":["Memerah ASI (pumping) secara berkala di tempat kerja dan memberikannya kepada bayi saat di rumah","Menghentikan total produksi ASI dan memberikan makanan padat keras","Memberikan susu kental manis komersial","Membawa bayi ke tempat kerja beracun","Membiarkan bayi kelaparan saat ibu bekerja"],"jawabanBenar":0,"pembahasan":"Manajemen laktasi melalui teknik memerah ASI di tempat kerja dan menyimpannya untuk diberikan saat ibu pulang adalah solusi terbaik mempertahankan pemberian ASI[cite: 1].","pembahasanPilihan":["Manajemen laktasi melalui teknik memerah ASI di tempat kerja dan menyimpannya untuk diberikan saat ibu pulang adalah solusi terbaik mempertahankan pemberian ASI[cite: 1].","Menghentikan ASI bertentangan dengan kesehatan anak.","Susu kental manis tidak direkomendasikan untuk bayi.","Membawa bayi ke tempat kerja berbahaya membahayakan anak.","Membiarkan bayi kelaparan melanggar hak anak."],"version":1},{"id":"kedkom2020-90","soal":"Di Puskesmas Kemayoran terdapat peningkatan kasus HIV/AIDS 50% dan akses ARV 10% akibat loss to follow up. Siapakah pihak yang paling tepat diundang dalam konseling kelompok untuk mencari solusi bersama?","opsi":["ODHIV, keluarga pendamping, kader, dan petugas layanan kesehatan","Hanya aparat kepolisian dan jaksa penuntut","Hanya anak-anak sekolah dasar wilayah setempat","Hanya petugas bea cukai pelabuhan","Hanya arsitek pembangunan gedung"],"jawabanBenar":0,"pembahasan":"Konseling kelompok penanggulangan HIV melibatkan Orang Dengan HIV (ODHIV), keluarga pendamping, kader kesehatan, dan tenaga medis layanan terkait agar penanganan bersifat komprehensif[cite: 1].","pembahasanPilihan":["Konseling kelompok penanggulangan HIV melibatkan Orang Dengan HIV (ODHIV), keluarga pendamping, kader kesehatan, dan tenaga medis layanan terkait agar penanganan bersifat komprehensif[cite: 1].","Aparat hukum dapat melanggar prinsip kerahasiaan medis.","Anak sekolah tidak relevan.","Bea cukai mengurus kepabeanan.","Arsitek mengurus bangunan."],"version":1},{"id":"kedkom2020-91","soal":"Gunung Merapi mengeluarkan erupsi awan panas (wedus gembel), apakah langkah awal darurat yang harus dilakukan oleh puskesmas di wilayah terdampak?","opsi":["Melakukan Penilaian Cepat Kesehatan / Rapid Health Assessment (RHA) dan koordinasi tanggap darurat","Menunggu instruksi tertulis dari luar negeri selama 1 bulan","Menutup seluruh puskesmas dan meninggalkan pasien","Melakukan seminar ilmiah kedokteran di hotel","Membuat laporan keuangan tahunan faskes"],"jawabanBenar":0,"pembahasan":"Saat terjadi bencana alam erupsi gunung berapi, langkah cepat awal yang dilakukan tim kesehatan puskesmas adalah melakukan Rapid Health Assessment (RHA) untuk menilai dampak korban dan kebutuhan medis darurat[cite: 1].","pembahasanPilihan":["Saat terjadi bencana alam erupsi gunung berapi, langkah cepat awal yang dilakukan tim kesehatan puskesmas adalah melakukan Rapid Health Assessment (RHA) untuk menilai dampak korban dan kebutuhan medis darurat[cite: 1].","Menunggu terlalu lama berakibat fatal bagi korban bencana.","Menutup puskesmas melanggar sumpah profesi dan tugas kemanusiaan.","Seminar tidak relevan dengan darurat bencana.","Laporan keuangan bukan prioritas saat bencana."],"version":1},{"id":"kedkom2020-92","soal":"Ny. X bekerja dan mengenalkan susu formula sejak usia 2 bulan agar anak tidak rewel saat ditinggal kerja. Upaya praktis apakah yang dapat dilakukan Ny. X agar tidak memutus pemberian ASI secara total?","opsi":["Memerah ASI di tempat kerja dan menyusui langsung pada saat berada di rumah","Mengganti total ASI dengan teh manis","Memberikan obat penenang tidur kepada bayi","Menitipkan bayi pada orang asing di jalan","Berhenti memberikan cairan apa pun ke bayi"],"jawabanBenar":0,"pembahasan":"Praktik pemerahan ASI saat bekerja dan menyusui langsung saat di rumah (manajemen laktasi ibu bekerja) adalah cara utama menjaga kesinambungan pemberian ASI[cite: 1].","pembahasanPilihan":["Praktik pemerahan ASI saat bekerja dan menyusui langsung saat di rumah (manajemen laktasi ibu bekerja) adalah cara utama menjaga kesinambungan pemberian ASI[cite: 1].","Teh manis tidak bernutrisi bagi bayi.","Obat penenang berbahaya dan ilegal bagi bayi.","Menitipkan pada orang asing membahayakan anak.","Bayi butuh asupan nutrisi dan cairan."],"version":1},{"id":"kedkom2020-93","soal":"Puskesmas di wilayah B mendirikan Posyandu di setiap RW di wilayah kerjanya. Apakah tujuan utama dari pendekatan dan pelibatan posyandu tersebut bagi masyarakat?","opsi":["Meningkatkan akses dan pemerataan pelayanan kesehatan dasar ibu dan anak di tingkat masyarakat","Menyelenggarakan operasi bedah jantung terbuka massal","Melakukan penambangan bijih besi warga","Menjual produk sandang komersial pabrikan","Menggantikan peran rumah sakit pusat rujukan"],"jawabanBenar":0,"pembahasan":"Posyandu dibentuk sebagai upaya kesehatan bersumber daya masyarakat (UKBM) untuk mendekatkan akses pelayanan kesehatan dasar ibu dan anak langsung ke tingkat dusun/RW[cite: 1].","pembahasanPilihan":["Posyandu dibentuk sebagai upaya kesehatan bersumber daya masyarakat (UKBM) untuk mendekatkan akses pelayanan kesehatan dasar ibu dan anak langsung ke tingkat dusun/RW[cite: 1].","Operasi bedah jantung ranah rumah sakit tersier.","Penambangan bukan fungsi kesehatan.","Menjual sandang ranah perdagangan.","Posyandu bukan pengganti RS rujukan."],"version":1},{"id":"kedkom2020-94","soal":"Kepala puskesmas mengumpulkan seluruh staf puskesmas untuk menentukan area masalah menggunakan musyawarah kelompok nominal tatap muka langsung. Apakah metode penentuan yang digunakan?","opsi":["Metode Delbecq (Nominal Group Technique)","Metode Hanlon kalkulasi rumit","Metode Delphi jarak jauh anonim","Metode Bryant matriks tunggal","Metode observasi pasif"],"jawabanBenar":0,"pembahasan":"Metode Delbecq adalah teknik musyawarah kelompok terstruktur secara tatap muka langsung untuk menetapkan prioritas masalah kesehatan[cite: 1].","pembahasanPilihan":["Metode Delbecq adalah teknik musyawarah kelompok terstruktur secara tatap muka langsung untuk menetapkan prioritas masalah kesehatan[cite: 1].","Hanlon berbasis rumus matematis.","Delphi tidak bertatap muka langsung.","Bryant menggunakan skoring kegawatan.","Observasi adalah pengamatan pasif."],"version":1},{"id":"kedkom2020-95","soal":"Berdasarkan batasan umum Organisasi Kesehatan Dunia (WHO), pada rentang usia berapakah seseorang dikategorikan sebagai lanjut usia (lansia)?","opsi":["60 tahun ke atas","20 hingga 30 tahun","40 hingga 45 tahun","10 hingga 15 tahun","0 hingga 5 tahun"],"jawabanBenar":0,"pembahasan":"Menurut pedoman resmi WHO serta Kemenkes RI, batasan kelompok usia lanjut (lansia) adalah 60 tahun ke atas[cite: 1].","pembahasanPilihan":["Menurut pedoman resmi WHO serta Kemenkes RI, batasan kelompok usia lanjut (lansia) adalah 60 tahun ke atas[cite: 1].","Usia 20-30 tahun adalah masa dewasa muda.","Usia 40-45 tahun adalah dewasa paruh baya.","Usia 10-15 tahun adalah masa remaja.","Usia 0-5 tahun adalah masa balita."],"version":1},{"id":"kedkom2020-96","soal":"Bapak N berusia 68 tahun. Iuran kepesertaan jaminan kesehatan BPJS miliknya dibayarkan sepenuhnya oleh pemerintah. Apakah status jenis kepesertaan JKN Bapak N tersebut?","opsi":["Penerima Bantuan Iuran (PBI)","Pekerja Penerima Upah (PPU)","Pekerja Bukan Penerima Upah (PBPU mandiri)","Bukan Pekerja golongan investor","Keluarga konglomerat swasta"],"jawabanBenar":0,"pembahasan":"Peserta JKN dari kalangan fakir miskin dan orang tidak mampu yang iurannya dibayarkan oleh pemerintah pusat/daerah dikategorikan sebagai Penerima Bantuan Iuran (PBI)[cite: 1].","pembahasanPilihan":["Peserta JKN dari kalangan fakir miskin dan orang tidak mampu yang iurannya dibayarkan oleh pemerintah pusat/daerah dikategorikan sebagai Penerima Bantuan Iuran (PBI)[cite: 1].","PPU adalah pekerja formal yang dipotong gaji bersama pemberi kerja.","PBPU adalah pekerja mandiri yang membayar iuran sendiri.","Bukan pekerja mencakup pensiunan atau investor.","Konglomerat bukan kategori jaminan sosial."],"version":1},{"id":"kedkom2020-97","soal":"Seorang dokter internship di wilayah Indonesia timur menemukan cakupan imunisasi polio masih rendah, sehingga ia membuat program vaksinasi massal. Jenis tingkat pencegahan apakah tindakan dokter tersebut?","opsi":["Specific protection (Perlindungan spesifik dalam pencegahan primer)","Early diagnosis and prompt treatment","Disability limitation","Rehabilitation medik","Health promotion murni tanpa vaksin"],"jawabanBenar":0,"pembahasan":"Pemberian imunisasi massal (seperti vaksin polio) untuk memberikan kekebalan spesifik terhadap penyakit tertentu termasuk dalam Specific protection pada level pencegahan primer[cite: 1].","pembahasanPilihan":["Pemberian imunisasi massal (seperti vaksin polio) untuk memberikan kekebalan spesifik terhadap penyakit tertentu termasuk dalam Specific protection pada level pencegahan primer[cite: 1].","Early diagnosis dilakukan saat orang sudah mulai sakit.","Disability limitation mencegah kecacatan lanjut.","Rehabilitasi memulihkan fungsi tubuh.","Health promotion adalah edukasi kesehatan umum."],"version":1},{"id":"kedkom2020-98","soal":"Ancaman pandemi yang sudah mereda kini disusul cuaca kemarau ekstrem yang menyebabkan kebakaran hutan dan polusi udara tinggi, memicu lonjakan gangguan pernapasan. Tingginya risiko gangguan kesehatan tersebut paling utama disebabkan oleh peningkatan faktor apa?","opsi":["Peningkatan hazard / ancaman lingkungan (polusi dan kebakaran)","Penurunan jumlah rumah sakit swasta","Kenaikan jumlah dokter spesialis bedah saraf","Penurunan kadar oksigen global secara mutlak","Kenaikan anggaran jaminan sosial"],"jawabanBenar":0,"pembahasan":"Lonjakan kasus gangguan pernapasan dipicu langsung oleh meningkatnya hazard eksternal berupa polusi udara ekstrem akibat kebakaran hutan[cite: 1].","pembahasanPilihan":["Lonjakan kasus gangguan pernapasan dipicu langsung oleh meningkatnya hazard eksternal berupa polusi udara ekstrem akibat kebakaran hutan[cite: 1].","Jumlah rumah sakit tidak memicu timbulnya polusi.","Jumlah dokter spesialis tidak berkaitan dengan polusi.","Kadar oksigen global tidak turun drastis secara global.","Anggaran sosial tidak memicu polusi."],"version":1},{"id":"kedkom2020-99","soal":"Pilar pembangunan berkelanjutan (SDGs) terdiri dari 4 pilar utama yaitu pembangunan sosial, lingkungan, ekonomi, serta hukum dan tata kelola. Ke dalam pilar apakah Tujuan SDGs Nomor 3 (Kehidupan sehat dan sejahtera) diklasifikasikan?","opsi":["Pilar Pembangunan Sosial","Pilar Pembangunan Lingkungan hidup","Pilar Pembangunan Ekonomi makro","Pilar Pembangunan Hukum dan pertahanan","Pilar Teknologi industri berat"],"jawabanBenar":0,"pembahasan":"Tujuan SDGs nomor 3 mengenai kesehatan dan kesejahteraan masyarakat masuk ke dalam kelompok Pilar Pembangunan Sosial[cite: 1].","pembahasanPilihan":["Tujuan SDGs nomor 3 mengenai kesehatan dan kesejahteraan masyarakat masuk ke dalam kelompok Pilar Pembangunan Sosial[cite: 1].","Lingkungan mencakup air bersih, sanitasi, dan ekosistem darat/laut.","Ekonomi mencakup pertumbuhan kerja layak dan industri.","Hukum mencakup keadilan dan kelembagaan kuat.","Teknologi bukan pilar utama SDGs."],"version":1},{"id":"kedkom2020-100","soal":"Dalam rangka pengembangan indikator program pemberantasan sarang nyamuk, indikator 'Angka Bebas Jentik' (ABJ) masuk ke dalam kategori indikator apa bagi sistem manajemen puskesmas?","opsi":["Indikator Output (Keluaran kegiatan langsung)","Indikator Input pendanaan","Indikator Outcome dampak kesehatan jangka panjang","Indikator Lingkungan sosial","Indikator Proses administrasi"],"jawabanBenar":0,"pembahasan":"Angka Bebas Jentik (ABJ) merupakan hasil langsung (output) dari pelaksanaan program pemantauan jentik berkala oleh petugas puskesmas dan kader[cite: 1].","pembahasanPilihan":["Angka Bebas Jentik (ABJ) merupakan hasil langsung (output) dari pelaksanaan program pemantauan jentik berkala oleh petugas puskesmas dan kader[cite: 1].","Input mencakup anggaran dan sarana.","Outcome mencakup penurunan insidens DBD jangka panjang.","Lingkungan bukan jenis indikator.","Proses mencakup jalannya kegiatan operasional."],"version":1},{"id":"kedkom2020-101","soal":"Pasien HIV meningkat 50%, akses ARV hanya 10%, akibat loss to follow up. Apakah langkah strategis utama yang dapat dilakukan untuk mengurangi hambatan konseling kelompok bagi pasien tersebut?","opsi":["Menyediakan layanan dukungan sebaya (peer support) serta memastikan jaminan kerahasiaan medis","Mempublikasikan nama pasien di media massa cetak","Mewajibkan pembayaran denda administratif yang besar","Menutup seluruh layanan kesehatan bagi penderita HIV","Melarang pasien berkonsultasi dengan dokter"],"jawabanBenar":0,"pembahasan":"Penyediaan dukungan sebaya (peer support) dan perlindungan kerahasiaan identitas sangat efektif mengatasi hambatan psikososial ODHA untuk mengikuti konseling[cite: 1].","pembahasanPilihan":["Penyediaan dukungan sebaya (peer support) dan perlindungan kerahasiaan identitas sangat efektif mengatasi hambatan psikososial ODHA untuk mengikuti konseling[cite: 1].","Publikasi massal melanggar hukum privasi dan etik kedokteran.","Denda memberatkan pasien.","Menutup layanan memperparah masalah kesehatan.","Melarang konsultasi melanggar hak pasien."],"version":1},{"id":"kedkom2020-102","soal":"Kasus HIV/AIDS di suatu wilayah naik 50%, dan akan diadakan konseling kelompok untuk menanggulangi loss to follow up. Siapakah pihak yang paling tepat diundang dalam kelompok konseling tersebut?","opsi":["Orang Dengan HIV (ODHIV), keluarga pendamping, kader kesehatan, dan petugas layanan","Hanya aparat kepolisian dan jaksa penuntut","Hanya anak-anak sekolah dasar di bawah umur","Hanya petugas bea cukai pelabuhan laut","Hanya arsitek perancang bangunan puskesmas"],"jawabanBenar":0,"pembahasan":"Konseling kelompok penanganan HIV melibatkan ODHIV, keluarga, kader, dan tenaga kesehatan terkait untuk membangun dukungan psikososial yang kuat[cite: 1].","pembahasanPilihan":["Konseling kelompok penanganan HIV melibatkan ODHIV, keluarga, kader, dan tenaga kesehatan terkait untuk membangun dukungan psikososial yang kuat[cite: 1].","Aparat penegak hukum dapat memicu stigma negatif.","Anak sekolah tidak relevan.","Bea cukai mengurus kepabeanan.","Arsitek merancang bangunan."],"version":1},{"id":"kedkom2020-103","soal":"Kewajiban seorang muslim untuk beribadah kepada Allah seperti mendirikan shalat, menunaikan zakat, dan menunaikan ibadah haji termasuk ke dalam penjagaan tujuan syariat Islam (Maqashid Syariah) di bidang apa?","opsi":["Hifzul Din (Memelihara agama)","Hifzul Mal (Memelihara harta)","Hifzul Nafs (Memelihara jiwa)","Hifzul Aql (Memelihara akal)","Hifzul Nasl (Memelihara keturunan)"],"jawabanBenar":0,"pembahasan":"Pelaksanaan ibadah utama seperti shalat, zakat, dan haji merupakan pilar utama dalam pemeliharaan dan penegakkan agama (Hifzul Din)[cite: 1].","pembahasanPilihan":["Pelaksanaan ibadah utama seperti shalat, zakat, dan haji merupakan pilar utama dalam pemeliharaan dan penegakkan agama (Hifzul Din)[cite: 1].","Hifzul mal berkaitan dengan pengelolaan kekayaan dan harta benda.","Hifzul nafs berkaitan dengan perlindungan nyawa raga.","Hifzul aql berkaitan dengan perlindungan akal pikiran.","Hifzul nasl berkaitan dengan perlindungan keturunan."],"version":1},{"id":"kedkom2020-104","soal":"Seorang perempuan berusia 48 tahun P0A1 datang dengan keluhan perdarahan pervaginam. Tampak pucat dan nadi meningkat. Dari anamnesis didapatkan pasien mengalami keputihan berbau busuk selama 1 tahun, dan akhir-akhir ini mengalami perdarahan saat berhubungan seksual (kontak berdarah). Pemeriksaan penapisan (skrining) apakah yang paling tepat untuk mendeteksi dini kelainan tersebut?","opsi":["Pemeriksaan Pap Smear / Inspeksi Visual Asam Asetat (IVA)","Pemeriksaan USG ginjal abdomen","Pemeriksaan kadar kolesterol darah total","Pemeriksaan rekam jantung EKG","Pemeriksaan fungsi tiroid darah"],"jawabanBenar":0,"pembahasan":"Gejala keputihan berbau dan perdarahan pascakoitus pada wanita usia 48 tahun merupakan tanda klinis kecurigaan kuat krisis serviks (kanker serviks), sehingga penapisan primernya adalah Pap Smear atau IVA[cite: 1].","pembahasanPilihan":["Gejala keputihan berbau dan perdarahan pascakoitus pada wanita usia 48 tahun merupakan tanda klinis kecurigaan kuat krisis serviks (kanker serviks), sehingga penapisan primernya adalah Pap Smear atau IVA[cite: 1].","USG ginjal tidak mendeteksi lesi pada serviks uteri.","Kolesterol menilai profil lemak lipid darah.","EKG merekam aktivitas kelistrikan jantung.","Fungsi tiroid menilai hormon kelenjar tiroid."],"version":1},{"id":"kedkom2020-105","soal":"Seorang dokter yang bertugas di pusat kesehatan haji melakukan tes kebugaran kepada calon jemaah sebelum diberangkatkan dan setelah itu akan melakukan surveilans selama proses ibadah haji berlangsung. Apakah jenis surveilans yang tepat berdasarkan sasaran penyelenggaraan tersebut?","opsi":["Surveilans Kesehatan Matra","Surveilans Penyakit Menular seksual","Surveilans Lingkungan pemukiman","Surveilans Gizi buruk balita","Surveilans Kanker payudara"],"jawabanBenar":0,"pembahasan":"Surveilans kesehatan matra adalah pengamatan epidemiologi khusus terhadap kesehatan jemaah haji, jemaah haji di Arab Saudi, jemaah haji di asrama, serta kondisi khusus matra lainnya[cite: 1].","pembahasanPilihan":["Surveilans kesehatan matra adalah pengamatan epidemiologi khusus terhadap kesehatan jemaah haji, jemaah haji di Arab Saudi, jemaah haji di asrama, serta kondisi khusus matra lainnya[cite: 1].","Surveilans PMS khusus infeksi menular seksual.","Surveilans lingkungan fokus pada sanitasi air dan udara.","Surveilans gizi fokus pada status antropometri anak.","Surveilans kanker fokus pada tumor ganas."],"version":1},{"id":"kedkom2020-106","soal":"Di suatu wilayah Puskesmas A selama bulan Januari-March mengalami KLB DBD. Jumlah warga yang meninggal sebanyak 10 orang dari 30 orang yang terkena DBD. Pada bulan April-Desember terdapat 50 orang terkena DBD. Berapakah Case Fatality Rate (CFR) DBD pada periode awal tersebut?","opsi":["33,33%","12,5%","0,125%","50%","10%"],"jawabanBenar":0,"pembahasan":"Case Fatality Rate (CFR) dihitung dari jumlah kematian dibagi jumlah kasus pada periode tersebut dikali 100%. Data menunjukkan 10 kematian dari 30 kasus (10/30 * 100% = 33,33%)[cite: 1].","pembahasanPilihan":["Case Fatality Rate (CFR) dihitung dari jumlah kematian dibagi jumlah kasus pada periode tersebut dikali 100%. Data menunjukkan 10 kematian dari 30 kasus (10/30 * 100% = 33,33%)[cite: 1].","12,5% adalah angka perhitungan keliru.","0,125% adalah kesalahan konversi desimal.","50% bukan hasil perhitungan data tersebut.","10% adalah jumlah kematian mentah."],"version":1},{"id":"kedkom2020-107","soal":"Dalam rangka diagnosis kanker serviks, klinik A menjalin kerja sama dengan laboratorium eksternal. Bahan pemeriksaan jaringan dikirim ke laboratorium rujukan. Jenis rujukan apakah yang dilakukan oleh klinik A?","opsi":["Rujukan Bahan Pemeriksaan (Rujukan Spesimen)","Rujukan Kasus medis darurat","Rujukan Tenaga ahli bedah","Rujukan Sarana ambulans","Rujukan Operasional administratif"],"jawabanBenar":0,"pembahasan":"Pengiriman sampel jaringan atau spesimen biologis pasien dari fasilitas kesehatan ke laboratorium rujukan dikategorikan sebagai rujukan bahan pemeriksaan / spesimen[cite: 1].","pembahasanPilihan":["Pengiriman sampel jaringan atau spesimen biologis pasien dari fasilitas kesehatan ke laboratorium rujukan dikategorikan sebagai rujukan bahan pemeriksaan / spesimen[cite: 1].","Rujukan kasus melibatkan perpindahan fisik pasien.","Rujukan tenaga melibatkan peminjaman dokter ahli.","Rujukan ambulans berkaitan dengan transportasi.","Rujukan operasional berkaitan dengan manajemen administrasi."],"version":1},{"id":"kedkom2020-108","soal":"Anak usia 2 tahun 1 bulan, BB 8.5 kg, TB 70 cm, keluhan BAB mencret 1 bulan, hanya diberi ASI, belum bisa duduk dan jalan, baru bisa bicara 'mama-papa'. Orang tua pemulung dengan 5 anak kecil. Instrumen skrining perkembangan apakah yang paling mudah dan direkomendasikan untuk digunakan oleh puskesmas serta guru PAUD?","opsi":["Kuesioner Pra Skrining Perkembangan (KPSP)","Skala klinis Bayley-III mendalam","Tes psikometrik Denver II lanjutan","Kuesioner psikiatrik PEDS","Skala autisme khusus"],"jawabanBenar":0,"pembahasan":"Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi yang praktis, cepat, dan mudah digunakan oleh tenaga puskesmas, guru PAUD, maupun orang tua[cite: 1].","pembahasanPilihan":["Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi yang praktis, cepat, dan mudah digunakan oleh tenaga puskesmas, guru PAUD, maupun orang tua[cite: 1].","Bayley-III adalah instrumen asesmen psikologis klinis yang rumit.","Denver II memerlukan pelatihan khusus dan waktu pemeriksaan lebih lama.","PEDS instrumen berbasis laporan orang tua, namun standar primer nasional adalah KPSP.","Skala autisme khusus untuk gangguan spektrum autis."],"version":1},{"id":"kedkom2020-109","soal":"Dokter layanan primer adalah fasilitas kesehatan tingkat pertama dalam program JKN yang menerima metode pembayaran kapitasi. Apakah arti dari metode pembayaran kapitasi tersebut?","opsi":["Fasilitas kesehatan dibayar di muka secara tetap per bulan berdasarkan jumlah peserta terdaftar, terlepas dari apakah peserta berobat atau tidak","Dokter dibayar tunai setiap kali selesai memeriksa pasien","Dokter dibayar berdasarkan durasi jam kerja di klinik","Dokter tidak mendapat bayaran sama sekali dari BPJS","Pembayaran dilakukan hanya jika pasien dioperasi besar"],"jawabanBenar":0,"pembahasan":"Kapitasi adalah metode pembayaran di muka kepada fasilitas kesehatan tingkat pertama berdasarkan jumlah jiwa peserta yang terdaftar setiap bulannya[cite: 1].","pembahasanPilihan":["Kapitasi adalah metode pembayaran di muka kepada fasilitas kesehatan tingkat pertama berdasarkan jumlah jiwa peserta yang terdaftar setiap bulannya[cite: 1].","Bayaran periksa per tindakan adalah fee-for-service.","Pembayaran berdasarkan jam adalah time-based.","Dokter menerima dana kapitasi sesuai ketentuan.","Operasi besar diatur dengan sistem INA-CBG di rumah sakit."],"version":1},{"id":"kedkom2020-110","soal":"Di suatu daerah selama setahun terjangkit DBD dari bulan Januari dengan 10 orang meninggal dari 30 orang terkena DBD. Pada periode berikutnya terdapat 50 orang terkena DBD. Berapakah Case Fatality Rate (CFR) pada periode pertama?","opsi":["33,33%","12,5%","0,125%","50%","10%"],"jawabanBenar":0,"pembahasan":"Case Fatality Rate dihitung dari jumlah kematian dibagi jumlah kasus (10/30 * 100% = 33,33%)[cite: 1].","pembahasanPilihan":["Case Fatality Rate dihitung dari jumlah kematian dibagi jumlah kasus (10/30 * 100% = 33,33%)[cite: 1].","12,5% adalah angka perhitungan keliru.","0,125% adalah kesalahan konversi desimal.","50% bukan hasil perhitungan data tersebut.","10% adalah jumlah kematian mentah."],"version":1},{"id":"kedkom2020-111","soal":"Penyakit nipah memiliki potensi wabah setelah pandemi Covid-19. Kemenkes melakukan upaya penanggulangan dengan menyediakan laboratorium sentral untuk monitoring kasus dan deteksi penyakit. Jenis surveilans apakah yang dilakukan untuk mengetahui patogen penyebab infeksi secara pasti?","opsi":["Surveilans Berbasis Laboratorium (Laboratory-based surveillance)","Surveilans demografi kependudukan","Surveilans keuangan instansi","Surveilans tata kota wilayah","Surveilans logistik obat"],"jawabanBenar":0,"pembahasan":"Surveilans berbasis laboratorium menggunakan spesimen biologis untuk mendeteksi, mengidentifikasi, dan memantau agen patogen penyebab penyakit secara akurat[cite: 1].","pembahasanPilihan":["Surveilans berbasis laboratorium menggunakan spesimen biologis untuk mendeteksi, mengidentifikasi, dan memantau agen patogen penyebab penyakit secara akurat[cite: 1].","Demografi mengkaji kependudukan.","Keuangan mengkaji anggaran.","Tata kota mengkaji wilayah.","Logistik obat mengkaji persediaan farmasi."],"version":1},{"id":"kedkom2020-112","soal":"Ibu meninggal dunia karena komplikasi perdarahan pascapersalinan. Ke dalam indikator kematian manakah data tersebut dicatat secara resmi?","opsi":["Angka Kematian Maternal (Maternal Mortality Rate / Ratio)","Angka Kematian Bayi (AKB)","Angka Kematian Kasar penduduk","Angka Kematian Anak balita","Angka Kematian Spesifik Usia Lanjut"],"jawabanBenar":0,"pembahasan":"Kematian wanita selama kehamilan, persalinan, atau nifas akibat komplikasi kehamilan dicatat ke dalam data Angka Kematian Maternal[cite: 1].","pembahasanPilihan":["Kematian wanita selama kehamilan, persalinan, atau nifas akibat komplikasi kehamilan dicatat ke dalam data Angka Kematian Maternal[cite: 1].","AKB mengukur kematian bayi di bawah usia 1 tahun.","AKK mengukur kematian seluruh populasi.","AKABA mengukur kematian anak di bawah 5 tahun.","AKL mengukur kematian lansia."],"version":1},{"id":"kedkom2020-113","soal":"Dalam metode penentuan prioritas masalah menggunakan metode Bryant, kriteria apakah yang digunakan untuk menilai tingkat keseriusan, tingkat keparahan, serta besarnya angka kesakitan dan kematian yang ditimbulkan?","opsi":["Seriousness (Tingkat keseriusan dan keparahan masalah)","Magnitude jumlah penduduk terkena","Emergency kedaruratan waktu","Affordability pembiayaan","Simplicity kemudahan teknis"],"jawabanBenar":0,"pembahasan":"Dalam metode Bryant, kriteria 'Seriousness' digunakan untuk menilai seberapa gawat, parah, serta besarnya morbiditas dan mortalitas dari suatu masalah kesehatan[cite: 1].","pembahasanPilihan":["Dalam metode Bryant, kriteria 'Seriousness' digunakan untuk menilai seberapa gawat, parah, serta besarnya morbiditas dan mortalitas dari suatu masalah kesehatan[cite: 1].","Magnitude menilai besar persentase populasi.","Emergency menilai kedaruratan.","Affordability menilai kemampuan pembiayaan.","Simplicity menilai kemudahan."],"version":1},{"id":"kedkom2020-114","soal":"Manakah di bawah ini yang merupakan landasan logis dalam mengangkat suatu kondisi menjadi area masalah kesehatan pada masyarakat binaan?","opsi":["Adanya kesenjangan (gap) yang nyata antara harapan/standar kesehatan dan kenyataan di lapangan","Tidak adanya data survei sama sekali","Keinginan pribadi petugas tanpa dasar data","Ketiadaan sama sekali masalah di masyarakat","Kepatuhan mutlak tanpa evaluasi"],"jawabanBenar":0,"pembahasan":"Definisi masalah kesehatan dalam manajemen program selalu bertumpu pada adanya kesenjangan (gap) antara target atau harapan (das sollen) dengan kenyataan di lapangan (das sein)[cite: 1].","pembahasanPilihan":["Definisi masalah kesehatan dalam manajemen program selalu bertumpu pada adanya kesenjangan (gap) antara target atau harapan (das sollen) dengan kenyataan di lapangan (das sein)[cite: 1].","Tanpa data survei, penentuan masalah tidak valid.","Keinginan pribadi tidak ilmiah.","Jika tidak ada masalah, maka tidak ada yang perlu diangkat.","Evaluasi mutlak diperlukan."],"version":1},{"id":"kedkom2020-115","soal":"Seorang dokter yang bertugas pada Pusat Kesehatan Haji melakukan tes kebugaran pada calon jemaah sebelum diberangkatkan dan setelah itu melakukan surveilans saat proses ibadah haji berlangsung. Apakah surveilans yang tepat berdasarkan sasaran penyelenggaraan?","opsi":["Surveilans Kesehatan Matra","Surveilans Penyakit Menular seksual","Surveilans Lingkungan pemukiman","Surveilans Gizi balita","Surveilans Kanker serviks"],"jawabanBenar":0,"pembahasan":"Pengamatan kesehatan khusus jemaah haji dikategorikan sebagai surveilans kesehatan matra[cite: 1].","pembahasanPilihan":["Pengamatan kesehatan khusus jemaah haji dikategorikan sebagai surveilans kesehatan matra[cite: 1].","PMS khusus infeksi menular seksual.","Lingkungan fokus pada sanitasi air.","Gizi fokus pada antropometri anak.","Kanker fokus pada tumor."],"version":1},{"id":"kedkom2020-116","soal":"Ny. A mau pergi haji 40 hari, menderita post stroke, kaki terasa sakit dan menggunakan kursi roda, serta akan menempuh penerbangan selama 8 jam. Saran apakah yang paling tepat diberikan oleh dokter untuk mencegah risiko kekakuan atau trombosis vena selama penerbangan?","opsi":["Melakukan latihan gerakan otot kaki / senam kaki secara berkala saat duduk di kursi pesawat","Tidur telungkup di lantai lorong pesawat selama 8 jam","Berlari cepat bolak-balik di dalam kabin pesawat","Tidak menggerakkan kaki sama sekali selama penerbangan","Meminum obat pelumpuh otot dosis tinggi"],"jawabanBenar":0,"pembahasan":"Untuk mencegah risiko DVT (Deep Vein Thrombosis) dan kaku akibat duduk lama di pesawat bagi pasien post-stroke, dianjurkan melakukan senam kaki sederhana secara berkala[cite: 1].","pembahasanPilihan":["Untuk mencegah risiko DVT (Deep Vein Thrombosis) dan kaku akibat duduk lama di pesawat bagi pasien post-stroke, dianjurkan melakukan senam kaki sederhana secara berkala[cite: 1].","Tidur di lantai lorong membahayakan keselamatan.","Berlari di kabin tidak mungkin dan berbahaya.","Tidak menggerakkan kaki justru memicu trombosis.","Obat pelumpuh otot tidak diindikasikan."],"version":1},{"id":"kedkom2020-117","soal":"Perempuan di Indonesia usia 20-24 tahun yang menikah sebelum umur 18 tahun jumlahnya cukup tinggi. Faktor utama apakah yang melatarbelakangi tingginya masalah kesehatan reproduksi remaja tersebut?","opsi":["Kehamilan remaja di luar nikah dan kurangnya pemahaman kesehatan reproduksi","Kewajiban melanjutkan studi pascasarjana","Ketersediaan fasilitas olahraga modern","Tingginya pendapatan finansial keluarga","Ketiadaan penduduk usia muda"],"jawabanBenar":0,"pembahasan":"Tingginya pernikahan anak dan masalah KRR dipicu oleh kehamilan remaja di luar nikah serta kurangnya edukasi kesehatan reproduksi yang memadai[cite: 1].","pembahasanPilihan":["Tingginya pernikahan anak dan masalah KRR dipicu oleh kehamilan remaja di luar nikah serta kurangnya edukasi kesehatan reproduksi yang memadai[cite: 1].","Studi lanjut menunda usia nikah.","Olahraga tidak memicu pernikahan anak.","Pendapatan tinggi tidak berkorelasi langsung dengan pernikahan dini paksa.","Populasi usia muda di Indonesia sangat besar."],"version":1},{"id":"kedkom2020-118","soal":"Sumber air bersih yang tercemar zat kimia berbahaya dapat mengganggu kesehatan penduduk yang mengonsumsinya. Dalam epidemiologi lingkungan, air berperan sebagai apakah dalam penularan penyakit tersebut?","opsi":["Media / Vehicle penularan zat pencemar","Faktor genetik internal manusia","Agen biologis hidup mandiri","Vektor serangga nyamuk","Hospen pejamu utama"],"jawabanBenar":0,"pembahasan":"Dalam rantai penularan penyakit lingkungan, air yang tercemar bahan kimia atau mikroorganisme bertindak sebagai media (vehicle) transmisi kepada manusia[cite: 1].","pembahasanPilihan":["Dalam rantai penularan penyakit lingkungan, air yang tercemar bahan kimia atau mikroorganisme bertindak sebagai media (vehicle) transmisi kepada manusia[cite: 1].","Genetik berasal dari kromosom internal.","Agen adalah zat kimia/mikrobanya itu sendiri.","Vektor adalah hewan perantara seperti nyamuk.","Pejamu adalah manusia yang terinfeksi."],"version":1},{"id":"kedkom2020-119","soal":"Di wilayah kerja Puskesmas A terjadi kasus kematian bayi dan sedang dilakukan audit maternal perinatal (AMP). Siapakah sumber narasumber utama yang bertugas memberikan informasi untuk pengisian formulir otopsi verbal?","opsi":["Keluarga pasien / pengasuh terdekat yang mendampingi almarhum","Petugas pajak daerah kabupaten","Aparat kepolisian sektor","Kepala dinas pekerjaan umum","Petugas pemadam kebakaran"],"jawabanBenar":0,"pembahasan":"Wawancara otopsi verbal dalam audit maternal perinatal dilakukan dengan menggali informasi kronologis dari keluarga terdekat atau pengasuh yang merawat pasien sebelum meninggal[cite: 1].","pembahasanPilihan":["Wawancara otopsi verbal dalam audit maternal perinatal dilakukan dengan menggali informasi kronologis dari keluarga terdekat atau pengasuh yang merawat pasien sebelum meninggal[cite: 1].","Petugas pajak tidak mengetahui riwayat medis.","Polisi menyelidiki tindak pidana.","Dinas PU mengurus infrastruktur.","Pemadam kebakaran memadamkan api."],"version":1},{"id":"kedkom2020-120","soal":"Puskesmas ingin menentukan prioritas masalah dan menggunakan metode Bryant. Apakah salah satu indikator parameter utama yang digunakan dalam metode tersebut?","opsi":["Seriousness (Tingkat keseriusan / keparahan masalah)","Warna cat dinding puskesmas","Jumlah kendaraan dinas kepala puskesmas","Luas halaman parkir klinik","Merk komputer staf administrasi"],"jawabanBenar":0,"pembahasan":"Dalam metode Bryant, parameter kriteria penilaian meliputi Seriousness (keseriusan/keparahan), Magnitude, dan sebagainya[cite: 1].","pembahasanPilihan":["Dalam metode Bryant, parameter kriteria penilaian meliputi Seriousness (keseriusan/keparahan), Magnitude, dan sebagainya[cite: 1].","Warna cat tidak relevan dengan prioritas kesehatan.","Kendaraan dinas tidak menilai masalah penyakit.","Luas parkir tidak menilai urgensi kesehatan.","Merk komputer tidak ada kaitannya."],"version":1},{"id":"kedkom2020-121","soal":"Puskesmas diatur secara resmi dalam peraturan menteri kesehatan nomor berapa?","opsi":["Permenkes No. 75 Tahun 2014 (atau pembaruannya Permenkes No. 43 Tahun 2019)","Permenkes No. 1 Tahun 2020","Permenkes No. 10 Tahun 2022","Permenkes No. 5 Tahun 2018","Permenkes No. 8 Tahun 2017"],"jawabanBenar":0,"pembahasan":"Regulasi historis utama mengenai Puskesmas diatur dalam Permenkes No. 75 Tahun 2014, yang kemudian disesuaikan melalui Permenkes No. 43 Tahun 2019[cite: 1].","pembahasanPilihan":["Regulasi historis utama mengenai Puskesmas diatur dalam Permenkes No. 75 Tahun 2014, yang kemudian disesuaikan melalui Permenkes No. 43 Tahun 2019[cite: 1].","Permenkes 1 Tahun 2020 mengatur hal lain.","Permenkes 10 Tahun 2022 mengatur substansi lain.","Permenkes 5 Tahun 2018 bukan tentang Puskesmas.","Permenkes 8 Tahun 2017 mengatur regulasi lain."],"version":1},{"id":"kedkom2020-122","soal":"Pilar pembangunan SDGs ada 4 yaitu pembangunan sosial, lingkungan, ekonomi, serta hukum dan tata kelola. Tujuan SDGs No. 3 (Kesehatan yang baik) termasuk ke dalam pilar apa?","opsi":["Pilar Pembangunan Sosial","Pilar Pembangunan Lingkungan","Pilar Pembangunan Hukum","Pilar Pembangunan Ekonomi","Semua pilar benar"],"jawabanBenar":0,"pembahasan":"Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan diklasifikasikan ke dalam Pilar Pembangunan Sosial[cite: 1].","pembahasanPilihan":["Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan diklasifikasikan ke dalam Pilar Pembangunan Sosial[cite: 1].","Lingkungan mencakup air dan sanitasi.","Hukum mencakup keadilan.","Ekonomi mencakup pertumbuhan industri.","Tidak semua pilar mencakup bidang kesehatan sosial secara langsung."],"version":1},{"id":"kedkom2020-123","soal":"Seorang ibu melahirkan setengah bulan lalu dan harus tetap bekerja. Agar bayi tidak rewel, ibu telah memperkenalkan susu formula. Bagaimana cara menyusui agar bayi tetap mendapatkan ASI secara optimal?","opsi":["Memerah ASI di tempat kerja dan menyusui langsung ketika ibu berada di rumah","Menghentikan total produksi ASI selamanya","Memberikan makanan padat nasi sejak usia 15 hari","Memberikan susu kental manis pekat","Membiarkan bayi tanpa ASI sama sekali"],"jawabanBenar":0,"pembahasan":"Manajemen laktasi melalui pemerahan ASI saat bekerja dan menyusui langsung saat di rumah adalah cara terbaik mempertahankan pemberian ASI bagi ibu bekerja[cite: 1].","pembahasanPilihan":["Manajemen laktasi melalui pemerahan ASI saat bekerja dan menyusui langsung saat di rumah adalah cara terbaik mempertahankan pemberian ASI bagi ibu bekerja[cite: 1].","Menghentikan ASI bertentangan dengan kesehatan anak.","Nasi usia 15 hari melanggar ASI eksklusif.","Susu kental manis tidak sehat untuk bayi.","Bayi membutuhkan nutrisi optimal."],"version":1},{"id":"kedkom2020-124","soal":"Berdasarkan hasil survei P2M Puskesmas didapatkan peningkatan HIV/AIDS 50%, tetapi akses ke layanan ARV hanya 10% akibat pasien loss to follow up. Langkah strategis apakah yang paling tepat untuk memperbaiki akses dan kepatuhan pengobatan tersebut?","opsi":["Membentuk kelompok dukungan sebaya (peer support) dan layanan komprehensif yang ramah pasien","Mengumumkan nama pasien di papan pengumuman kelurahan","Memberikan sanksi denda uang kepada pasien","Menutup seluruh klinik khusus HIV","Melarang pasien meminum obat ARV"],"jawabanBenar":0,"pembahasan":"Pembentukan kelompok dukungan sebaya (peer support) dan penyediaan layanan khusus yang ramah terbukti meningkatkan kepatuhan serta akses ARV pada pasien HIV[cite: 1].","pembahasanPilihan":["Pembentukan kelompok dukungan sebaya (peer support) dan penyediaan layanan khusus yang ramah terbukti meningkatkan kepatuhan serta akses ARV pada pasien HIV[cite: 1].","Mengumumkan nama melanggar hukum privasi medis.","Sanksi denda memberatkan pasien.","Menutup klinik memperparah wabah.","Melarang minum obat membahayakan nyawa pasien."],"version":1},{"id":"kedkom2020-125","soal":"Ayat dalam Al-Qur'an yang memerintahkan agar berbuat baik kepada orang tua (birrul walidain) terdapat pada surat dan ayat berapa?","opsi":["Surah Al-Isra' ayat 23-24","Surah Al-Baqarah ayat 10","Surah An-Nur ayat 2","Surah Al-Ma'idah ayat 5","Surah Al-An'am ayat 1"],"jawabanBenar":0,"pembahasan":"Perintah berbakti kepada kedua orang tua termuat dengan jelas dalam Al-Qur'an Surah Al-Isra' ayat 23-24[cite: 1].","pembahasanPilihan":["Perintah berbakti kepada kedua orang tua termuat dengan jelas dalam Al-Qur'an Surah Al-Isra' ayat 23-24[cite: 1].","Al-Baqarah 10 tentang penyakit hati orang munafik.","An-Nur 2 tentang hukum zina.","Al-Ma'idah 5 tentang makanan ahli kitab.","Al-An'am 1 tentang pujian kepada Allah."],"version":1},{"id":"kedkom2020-126","soal":"SDGs terbagi menjadi 4 pilar pembangunan (Sosial, Ekonomi, Lingkungan, Hukum dan Tata Kelola). Tujuan SDGs ke-3 termasuk ke dalam pilar apa?","opsi":["Pilar Pembangunan Sosial","Pilar Pembangunan Ekonomi","Pilar Pembangunan Lingkungan","Pilar Pembangunan Hukum","Semua pilar"],"jawabanBenar":0,"pembahasan":"Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan masuk ke dalam Pilar Pembangunan Sosial[cite: 1].","pembahasanPilihan":["Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan masuk ke dalam Pilar Pembangunan Sosial[cite: 1].","Ekonomi mencakup pertumbuhan kerja.","Lingkungan mencakup ekosistem.","Hukum mencakup keadilan.","Tidak semua pilar mencakup bidang sosial kesehatan."],"version":1},{"id":"kedkom2020-127","soal":"Pasien akan berangkat haji 40 hari, cuaca terik, memiliki riwayat stroke. Apakah anjuran pencegahan kesehatan yang paling penting diperhatikan selama di tanah suci?","opsi":["Cukup minum air putih secara teratur untuk mencegah dehidrasi dan menggunakan pelindung panas","Berjemur tanpa payung di tengah hari bolong","Menghindari minum air sama sekali","Memakai pakaian musim dingin tebal berlapis","Berhenti minum obat stroke secara total"],"jawabanBenar":0,"pembahasan":"Menjaga hidrasi tubuh dengan minum air putih teratur serta melindungi diri dari terik matahari sangat penting bagi jemaah lansia/risiko tinggi seperti riwayat stroke[cite: 1].","pembahasanPilihan":["Menjaga hidrasi tubuh dengan minum air putih teratur serta melindungi diri dari terik matahari sangat penting bagi jemaah lansia/risiko tinggi seperti riwayat stroke[cite: 1].","Berjemur tanpa pelindung memicu heat stroke.","Menghindari air memicu dehidrasi berat.","Pakaian tebal memicu sengatan panas.","Berhenti obat stroke membahayakan kesehatan otak."],"version":1},{"id":"kedkom2020-128","soal":"Dari 17 tujuan SDGs, terdapat beberapa tujuan yang secara langsung berkaitan dengan bidang kesehatan. Tujuan manakah yang mencakup bidang kesehatan dalam SDGs?","opsi":["Tujuan 2, 3, 5, dan 6 (serta keterkaitan gizi, kesehatan, air, dan sanitasi)","Tujuan 7, 8, 9, dan 10","Tujuan 11, 12, 13, dan 14","Tujuan 12, 13, 14, dan 15","Tujuan 14, 15, 16, dan 17"],"jawabanBenar":0,"pembahasan":"Tujuan SDGs yang erat kaitannya dengan kesehatan meliputi Tujuan 2 (Zero Hunger / gizi), Tujuan 3 (Good Health / kesehatan), Tujuan 5 (Gender), dan Tujuan 6 (Clean Water / sanitasi air)[cite: 1].","pembahasanPilihan":["Tujuan SDGs yang erat kaitannya dengan kesehatan meliputi Tujuan 2 (Zero Hunger / gizi), Tujuan 3 (Good Health / kesehatan), Tujuan 5 (Gender), dan Tujuan 6 (Clean Water / sanitasi air)[cite: 1].","Tujuan 7-10 untuk energi dan ekonomi.","Tujuan 11-14 untuk kota dan iklim.","Tujuan 12-15 untuk produksi dan daratan.","Tujuan 14-17 untuk lautan dan kemitraan."],"version":1},{"id":"kedkom2020-129","soal":"Surveilans kesehatan masyarakat yang berfokus pada pemantauan gejala-gejala klinis awal sebelum diagnosis laboratorium definitif tegak dikenal sebagai:","opsi":["Surveilans sindromik (Syndromic surveillance)","Surveilans bedah ortopedi","Surveilans keuangan korporasi","Surveilans logistik apotek","Surveilans pariwisata asing"],"jawabanBenar":0,"pembahasan":"Surveilans sindromik menggunakan pengumpulan data gejala klinis awal (seperti sindrom demam atau batuk) untuk mendeteksi potensi wabah lebih awal sebelum hasil lab keluar[cite: 1].","pembahasanPilihan":["Surveilans sindromik menggunakan pengumpulan data gejala klinis awal (seperti sindrom demam atau batuk) untuk mendeteksi potensi wabah lebih awal sebelum hasil lab keluar[cite: 1].","Ortopedi berkaitan dengan bedah tulang.","Keuangan berkaitan dengan akuntansi.","Logistik apotek mengurus obat.","Pariwisata mengurus turis."],"version":1},{"id":"kedkom2020-130","soal":"Dinas Kesehatan Kota X mengevaluasi sistem surveilans DBD. Penerimaan, dukungan, dan kesediaan masyarakat serta organisasi yang berpartisipasi sangat positif. Sifat karakteristik sistem surveilans apakah yang ditunjukkan?","opsi":["Akseptabilitas (Acceptability)","Kesederhanaan (Simplicity)","Fleksibilitas sistem","Stabilitas data","Sensitivitas klinis"],"jawabanBenar":0,"pembahasan":"Akseptabilitas (acceptability) dalam atribut surveilans mencerminkan tingkat kesediaan dan penerimaan individu maupun organisasi untuk berpartisipasi aktif dalam sistem pelaporan[cite: 1].","pembahasanPilihan":["Akseptabilitas (acceptability) dalam atribut surveilans mencerminkan tingkat kesediaan dan penerimaan individu maupun organisasi untuk berpartisipasi aktif dalam sistem pelaporan[cite: 1].","Kesederhanaan berkaitan dengan kemudahan operasional alur.","Fleksibilitas menilai kemampuan beradaptasi.","Stabilitas menilai keajegan data.","Sensitivitas menilai kemampuan mendeteksi kasus."],"version":1},{"id":"kedkom2020-131","soal":"Kewajiban seorang muslim untuk beribadah kepada Allah seperti mendirikan shalat, menunaikan zakat, dan berpuasa termasuk ke dalam tujuan syariat Islam (Maqashid Syariah) dalam hal memelihara apa?","opsi":["Hifzun Din (Memelihara agama)","Hifzun Mal (Memelihara harta)","Hifzun Nafs (Memelihara jiwa)","Hifzun Aql (Memelihara akal)","Hifzun Nasl (Memelihara keturunan)"],"jawabanBenar":0,"pembahasan":"Penegakkan ibadah pokok seperti shalat dan zakat merupakan wujud utama pemeliharaan agama (Hifzun Din) dalam maqashid syariah[cite: 1].","pembahasanPilihan":["Penegakkan ibadah pokok seperti shalat dan zakat merupakan wujud utama pemeliharaan agama (Hifzun Din) dalam maqashid syariah[cite: 1].","Hifzun mal berkaitan dengan harta kekayaan.","Hifzun nafs berkaitan dengan perlindungan nyawa.","Hifzun aql berkaitan dengan akal pikiran.","Hifzun nasl berkaitan dengan keturunan."],"version":1},{"id":"kedkom2020-132","soal":"Seorang perempuan berusia 70 tahun dengan riwayat hipertensi dan DM hendak melakukan perjalanan haji 40 hari menggunakan pesawat selama 8 jam. Saran apakah yang paling tepat diberikan kepada pasien selama perjalanan di pesawat untuk mencegah komplikasi sirkulasi darah?","opsi":["Melakukan latihan senam kaki / peregangan otot secara berkala saat duduk di kursi pesawat","Tidur telungkup di lantai kabin pesawat selama 8 jam","Berlari cepat bolak-balik di lorong sempit","Tidak bergerak sama sekali selama penerbangan","Minum obat tidur dosis tinggi"],"jawabanBenar":0,"pembahasan":"Untuk mencegah risiko trombosis vena akibat imobilitas lama pada lansia di pesawat, dianjurkan melakukan senam kaki sederhana dan peregangan berkala[cite: 1].","pembahasanPilihan":["Untuk mencegah risiko trombosis vena akibat imobilitas lama pada lansia di pesawat, dianjurkan melakukan senam kaki sederhana dan peregangan berkala[cite: 1].","Tidur di lantai kabin membahayakan keselamatan.","Berlari di lorong tidak aman.","Tidak bergerak justru memicu pembekuan darah.","Obat tidur dosis tinggi tidak diindikasikan."],"version":1},{"id":"kedkom2020-133","soal":"Dinas Kesehatan Kota X melakukan surveilans DBD. Pada observasi lapangan didapatkan tingkat partisipasi dan penerimaan masyarakat yang sangat positif terhadap sistem tersebut. Atribut karakteristik apakah yang dimaksud?","opsi":["Akseptabilitas (Acceptability)","Kesederhanaan (Simplicity)","Fleksibilitas operasional","Keluasan cakupan","Nilai prediktif positif"],"jawabanBenar":0,"pembahasan":"Tingkat penerimaan dan kesediaan masyarakat untuk berpartisipasi dalam sistem surveilans mencerminkan atribut akseptabilitas (acceptability)[cite: 1].","pembahasanPilihan":["Tingkat penerimaan dan kesediaan masyarakat untuk berpartisipasi dalam sistem surveilans mencerminkan atribut akseptabilitas (acceptability)[cite: 1].","Kesederhanaan menilai kemudahan alur.","Fleksibilitas menilai adaptasi sistem.","Cakupan menilai luas wilayah.","Nilai prediktif menilai ketepatan diagnosis."],"version":1},{"id":"kedkom2020-134","soal":"Dokter A sedang bertugas internship di puskesmas wilayah Indonesia timur dan menyadari cakupan imunisasi polio belum merata, sehingga ia berinisiatif membuat program imunisasi polio massal. Tindakan pencegahan apakah yang dilakukan oleh dokter A?","opsi":["Specific protection (Perlindungan spesifik dalam pencegahan primer)","Early diagnosis and prompt treatment","Disability limitation","Rehabilitation medis total","Health promotion tanpa intervensi spesifik"],"jawabanBenar":0,"pembahasan":"Pemberian vaksinasi massal (seperti imunisasi polio) untuk memberikan kekebalan spesifik terhadap penyakit dikategorikan sebagai Specific protection dalam tingkat pencegahan primer[cite: 1].","pembahasanPilihan":["Pemberian vaksinasi massal (seperti imunisasi polio) untuk memberikan kekebalan spesifik terhadap penyakit dikategorikan sebagai Specific protection dalam tingkat pencegahan primer[cite: 1].","Early diagnosis dilakukan saat mulai timbul gejala sakit.","Disability limitation mencegah kecacatan.","Rehabilitasi memulihkan fungsi tubuh pasca sakit.","Health promotion adalah penyuluhan kesehatan umum."],"version":1},{"id":"kedkom2020-135","soal":"Ny. Z baru melahirkan anak kedua, sibuk bekerja sehingga kesulitan memberikan ASI. Mengingat anak pertama diberi sufor sejak usia 2 bulan agar tidak rewel saat ditinggal kerja, upaya praktis apakah yang dapat dilakukan Ny. Z agar bayinya tetap mendapatkan ASI?","opsi":["Memerah ASI (pumping) saat bekerja dan menyusui langsung saat di rumah","Menghentikan produksi ASI secara permanen","Memberikan bubur instan dewasa","Membawa bayi ke tempat kerja berbahaya","Membiarkan bayi kelaparan"],"jawabanBenar":0,"pembahasan":"Manajemen laktasi melalui pemerahan ASI saat bekerja dan menyusui langsung di rumah adalah solusi terbaik bagi ibu bekerja agar anak tetap memperoleh ASI[cite: 1].","pembahasanPilihan":["Manajemen laktasi melalui pemerahan ASI saat bekerja dan menyusui langsung di rumah adalah solusi terbaik bagi ibu bekerja agar anak tetap memperoleh ASI[cite: 1].","Menghentikan ASI bertentangan dengan kesehatan anak.","Bubur instan bukan untuk bayi baru lahir.","Membawa ke tempat kerja berbahaya mengancam keselamatan bayi.","Membiarkan kelaparan melanggar hak anak."],"version":1},{"id":"kedkom2020-136","soal":"Ketika melakukan evaluasi program, dokter X menemukan bahwa cakupan ASI eksklusif berada di bawah target. Apakah akar penyebab utama dalam subsistem sumber daya manusia (Man) yang sering mendasari hal tersebut?","opsi":["Keterbatasan jumlah dan kapasitas tenaga penyuluh / konselor laktasi terlatih di wilayah kerja","Kelebihan anggaran dana operasional puskesmas","Ketersediaan gedung puskesmas yang terlalu megah","Jumlah pasien yang sedikit","Ketersediaan alat bedah ortopedi yang lengkap"],"jawabanBenar":0,"pembahasan":"Keterbatasan jumlah dan kompetensi tenaga kesehatan (konselor laktasi/penyuluh gizi) di puskesmas dikategorikan sebagai hambatan pada subsistem Man (sumber daya manusia)[cite: 1].","pembahasanPilihan":["Keterbatasan jumlah dan kompetensi tenaga kesehatan (konselor laktasi/penyuluh gizi) di puskesmas dikategorikan sebagai hambatan pada subsistem Man (sumber daya manusia)[cite: 1].","Kelebihan anggaran masuk ke subsistem uang (money).","Gedung megah masuk ke sarana fisik.","Jumlah pasien bukan kendala SDM internal.","Alat bedah tidak berhubungan dengan konseling ASI."],"version":1},{"id":"kedkom2020-137","soal":"Di wilayah kerja puskesmas terjadi kematian bayi dan dilakukan audit maternal perinatal (AMP). Siapakah narasumber utama yang paling tepat diwawancarai untuk pengisian formulir otopsi verbal?","opsi":["Keluarga pasien / pengasuh terdekat yang merawat almarhum","Petugas pajak daerah kabupaten","Aparat kepolisian sektor","Kepala dinas pekerjaan umum","Petugas pemadam kebakaran"],"jawabanBenar":0,"pembahasan":"Otopsi verbal dalam audit maternal perinatal memerlukan informasi kronologis dari keluarga atau pengasuh terdekat yang mendampingi pasien sebelum meninggal[cite: 1].","pembahasanPilihan":["Otopsi verbal dalam audit maternal perinatal memerlukan informasi kronologis dari keluarga atau pengasuh terdekat yang mendampingi pasien sebelum meninggal[cite: 1].","Petugas pajak tidak menguasai riwayat medis.","Polisi menyelidiki kriminalitas.","Dinas PU mengurus infrastruktur.","Pemadam kebakaran memadamkan api."],"version":1},{"id":"kedkom2020-138","soal":"Berbagai kontrasepsi memiliki keuntungan dan kerugian masing-masing. Manakah di bawah ini yang merupakan salah satu keuntungan utama dari penggunaan kontrasepsi implant (susuk KB)?","opsi":["Merupakan metode kontrasepsi jangka panjang dengan efektivitas tinggi dan tidak mengganggu produksi ASI","Harus diganti setiap 1 jam sekali setiap hari","Menyebabkan kemandulan permanen selamanya yang tidak bisa dipulihkan","Meningkatkan risiko infeksi saluran cerna akut","Mengharuskan pembedahan mayor di ruang ICU rumah sakit pusat"],"jawabanBenar":0,"pembahasan":"Kontrasepsi implant (susuk KB) adalah metode kontrasepsi jangka panjang (MKJP) yang sangat efektif, praktis, dan aman bagi ibu menyusui karena berbasis progestin tanpa menekan produksi ASI[cite: 1].","pembahasanPilihan":["Kontrasepsi implant (susuk KB) adalah metode kontrasepsi jangka panjang (MKJP) yang sangat efektif, praktis, dan aman bagi ibu menyusui karena berbasis progestin tanpa menekan produksi ASI[cite: 1].","Implant dipasang untuk jangka waktu bertahun-tahun (3-5 tahun), bukan harian.","Kesuburan dapat segera pulih setelah implant dilepas.","Implant tidak memicu infeksi saluran cerna.","Pemasangan dilakukan secara minor di bawah kulit lengan, bukan bedah mayor ICU."],"version":1},{"id":"kedkom2020-139","soal":"Pilar pembangunan SDGs ada 4 yaitu pilar pembangunan sosial, lingkungan, ekonomi, serta hukum dan tata kelola. Tujuan SDGs No. 3 termasuk ke dalam pilar apa?","opsi":["Pilar Pembangunan Sosial","Pilar Pembangunan Lingkungan","Pilar Pembangunan Hukum","Pilar Pembangunan Ekonomi","Semua pilar"],"jawabanBenar":0,"pembahasan":"Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan masyarakat diklasifikasikan ke dalam Pilar Pembangunan Sosial[cite: 1].","pembahasanPilihan":["Tujuan pembangunan berkelanjutan nomor 3 mengenai kesehatan dan kesejahteraan masyarakat diklasifikasikan ke dalam Pilar Pembangunan Sosial[cite: 1].","Lingkungan mencakup ekosistem air dan darat.","Hukum mencakup keadilan.","Ekonomi mencakup pertumbuhan industri.","Tidak semua pilar mencakup bidang sosial kesehatan."],"version":1},{"id":"kedkom2020-140","soal":"Skenario mengenai seorang nenek lansia yang ikut serta dalam Program Keluarga Harapan (PKH). Apakah tujuan utama dari fungsi program bantuan sosial tersebut bagi kelompok lansia rentan?","opsi":["Meningkatkan kesejahteraan sosial dan kualitas hidup lansia kurang mampu","Memberangkatkan seluruh lansia ke luar angkasa","Memberikan pelatihan atlet angkat besi profesional","Menjadikan lansia sebagai pekerja pabrik berat","Menghilangkan hak pilih pemilu warga lansia"],"jawabanBenar":0,"pembahasan":"Program Keluarga Harapan (PKH) bagi komponen kesejahteraan sosial lanjut usia bertujuan untuk meningkatkan taraf kesejahteraan sosial dan kualitas hidup lansia rentan[cite: 1].","pembahasanPilihan":["Program Keluarga Harapan (PKH) bagi komponen kesejahteraan sosial lanjut usia bertujuan untuk meningkatkan taraf kesejahteraan sosial dan kualitas hidup lansia rentan[cite: 1].","Ke luar angkasa tidak relevan.","Lansia tidak dilatih angkat besi berat.","PKH melindungi lansia, bukan mempekerjakan di pabrik berat.","Hak pilih dijamin konstitusi."],"version":1},{"id":"kedkom2020-141","soal":"Masalah kesehatan yang diangkat menjadi area masalah di masyarakat binaan merupakan masalah yang memenuhi kriteria apa?","opsi":["Terdapat kesenjangan (gap) yang nyata antara harapan dan kenyataan di masyarakat","Tidak didasarkan pada data survei sama sekali","Merupakan rekayasa fiksi tanpa kejadian nyata","Sengaja disembunyikan dari tenaga kesehatan","Tidak menimbulkan dampak merugikan"],"jawabanBenar":0,"pembahasan":"Penentuan area masalah kesehatan masyarakat selalu berpijak pada adanya kesenjangan yang objektif antara standar/harapan kesehatan dan kenyataan di lapangan[cite: 1].","pembahasanPilihan":["Penentuan area masalah kesehatan masyarakat selalu berpijak pada adanya kesenjangan yang objektif antara standar/harapan kesehatan dan kenyataan di lapangan[cite: 1].","Tanpa data survei, penentuan tidak valid.","Masalah harus nyata terjadi di lapangan.","Masalah harus dianalisis terbuka.","Masalah pasti menimbulkan dampak."],"version":1},{"id":"kedkom2020-142","soal":"Lansia yang sudah tidak bekerja ikut serta dalam Program Keluarga Harapan (PKH). Apakah fungsi utama dari program perlindungan sosial tersebut?","opsi":["Meningkatkan kesejahteraan sosial dan perlindungan jaminan hidup lansia","Memaksa lansia bekerja di sektor konstruksi","Mengurangi hak-hak dasar warga negara","Menaikkan harga kebutuhan pokok secara drastis","Menutup seluruh fasilitas panti jompo"],"jawabanBenar":0,"pembahasan":"Fungsi utama PKH komponen kesejahteraan sosial bagi lansia adalah memberikan perlindungan sosial dan meningkatkan kesejahteraan hidup mereka[cite: 1].","pembahasanPilihan":["Fungsi utama PKH komponen kesejahteraan sosial bagi lansia adalah memberikan perlindungan sosial dan meningkatkan kesejahteraan hidup mereka[cite: 1].","PKH bukan program pekerja konstruksi.","Program sosial melindungi hak warga.","PKH meringankan beban, bukan menaikkan harga.","Panti jompo dikelola terpisah."],"version":1},{"id":"kedkom2020-143","soal":"Di Negara X, tercatat 250 orang sakit jantung pada tahun 2022 dengan jumlah penduduk total 5.000.000 jiwa. Berapakah angka kejadian (insidens rate) per 100 penduduk di negara tersebut?","opsi":["0,005 per 100 penduduk (atau 0,005%)","0,25 per 100 penduduk","50 per 100 penduduk","250 per 100 penduduk","5,0 per 100 penduduk"],"jawabanBenar":0,"pembahasan":"Insidens rate dihitung dengan membagi jumlah kasus baru (250) dengan total populasi (5.000.000), menghasilkan 0,00005 per 1 penduduk atau setara dengan 0,005 per 100 penduduk[cite: 1].","pembahasanPilihan":["Insidens rate dihitung dengan membagi jumlah kasus baru (250) dengan total populasi (5.000.000), menghasilkan 0,00005 per 1 penduduk atau setara dengan 0,005 per 100 penduduk[cite: 1].","0,25 adalah hasil perhitungan yang salah.","50 adalah nilai yang keliru.","250 adalah jumlah kasus absolut.","5,0 adalah kesalahan perkalian."],"version":1},{"id":"kedkom2020-144","soal":"Solusi yang paling tepat dan komprehensif dalam menangani permasalahan kesehatan reproduksi remaja (seperti tingginya angka pernikahan dini dan risiko kespro) di masyarakat adalah:","opsi":["Sosialisasi dan edukasi kesehatan reproduksi remaja (KRR) secara masif serta penyuluhan konseling sebaya","Menganjurkan seluruh anak putus sekolah di bawah usia 12 tahun","Menutup seluruh fasilitas akses informasi internet","Menghapus mata pelajaran biologi dan kesehatan di sekolah","Melarang remaja berinteraksi sosial selamanya"],"jawabanBenar":0,"pembahasan":"Solusi preventif utama untuk mengatasi masalah kesehatan reproduksi remaja adalah edukasi KRR yang komprehensif serta pemberdayaan konseling sebaya yang tepat sasaran[cite: 1].","pembahasanPilihan":["Solusi preventif utama untuk mengatasi masalah kesehatan reproduksi remaja adalah edukasi KRR yang komprehensif serta pemberdayaan konseling sebaya yang tepat sasaran[cite: 1].","Meminta anak putus sekolah memperburuk masa depan.","Menutup internet bukan solusi edukasi.","Menghapus pelajaran kesehatan memperparah ketidaktahuan.","Melarang interaksi sosial bertentangan dengan psikologi perkembangan."],"version":1},{"id":"kedkom2020-145","soal":"Dokter primer adalah fasilitas pelayanan kesehatan tingkat pertama dalam program JKN yang menerima metode pembayaran kapitasi. Apakah arti dari metode kapitasi tersebut?","opsi":["Fasilitas kesehatan dibayar di muka secara tetap per bulan berdasarkan jumlah peserta terdaftar, terlepas dari apakah peserta berobat atau tidak","Dokter dibayar tunai setiap kali selesai memeriksa pasien","Dokter dibayar berdasarkan durasi jam kerja di klinik","Dokter tidak mendapat bayaran sama sekali dari BPJS","Pembayaran dilakukan hanya jika pasien dioperasi besar"],"jawabanBenar":0,"pembahasan":"Kapitasi adalah sistem pembayaran di muka kepada FKTP berdasarkan jumlah peserta terdaftar setiap bulannya tanpa melihat frekuensi kunjungan berobat[cite: 1].","pembahasanPilihan":["Kapitasi adalah sistem pembayaran di muka kepada FKTP berdasarkan jumlah peserta terdaftar setiap bulannya tanpa melihat frekuensi kunjungan berobat[cite: 1].","Bayaran periksa per tindakan adalah fee-for-service.","Pembayaran berdasarkan jam adalah time-based.","Dokter menerima dana kapitasi sesuai ketentuan.","Operasi besar diatur dengan sistem INA-CBG di rumah sakit."],"version":1},{"id":"kedkom2020-146","soal":"Hitunglah angka kejadian (insidens rate) jika di suatu daerah terdapat 5.000.000 penduduk dan yang terkena penyakit jantung adalah 500 orang.","opsi":["0,01 per 100 penduduk (atau 0,01%)","0,5 per 100 penduduk","0,125 per 100 penduduk","10 per 100 penduduk","50 per 100 penduduk"],"jawabanBenar":0,"pembahasan":"Insidens rate dihitung dari jumlah kasus (500) dibagi total populasi (5.000.000), menghasilkan 0,0001 per orang atau 0,01 per 100 penduduk (0,01%)[cite: 1].","pembahasanPilihan":["Insidens rate dihitung dari jumlah kasus (500) dibagi total populasi (5.000.000), menghasilkan 0,0001 per orang atau 0,01 per 100 penduduk (0,01%)[cite: 1].","0,5 adalah hasil perkalian yang salah.","0,125 bukan hasil kalkulasi data tersebut.","10 adalah nilai keliru.","50 adalah nilai keliru."],"version":1},{"id":"kedkom2020-147","soal":"Indonesia masih memiliki permasalahan kesehatan reproduksi yang cukup tinggi, salah satunya karena sebagian masyarakat menganggap tabu membicarakannya. Manakah pernyataan yang paling benar mengenai definisi kesehatan reproduksi?","opsi":["Keadaan sehat secara fisik, mental, dan sosial secara utuh, tidak semata-mata bebas dari penyakit atau kecacatan yang berkaitan dengan sistem, fungsi, dan proses reproduksi","Kesehatan reproduksi hanya penting bagi kaum perempuan saja","Pengetahuan kespro hanya boleh diberikan setelah seseorang menikah","Kesehatan reproduksi tidak ada hubungannya dengan aspek mental sosial","Kesehatan reproduksi hanya berfokus pada saat proses persalinan bayi"],"jawabanBenar":0,"pembahasan":"Definisi resmi Kesehatan Reproduksi menurut WHO dan Kemenkes mencakup keadaan sehat fisik, mental, dan sosial secara utuh dalam segala hal yang berkaitan dengan sistem, fungsi, dan proses reproduksi[cite: 1].","pembahasanPilihan":["Definisi resmi Kesehatan Reproduksi menurut WHO dan Kemenkes mencakup keadaan sehat fisik, mental, dan sosial secara utuh dalam segala hal yang berkaitan dengan sistem, fungsi, dan proses reproduksi[cite: 1].","Kesehatan reproduksi penting bagi laki-laki maupun perempuan.","Pengetahuan kespro harus diberikan sejak remaja secara edukatif.","Aspek mental dan sosial merupakan bagian integral dari definisi sehat.","Kespro mencakup siklus hidup yang luas, bukan hanya saat persalinan."],"version":1},{"id":"kedkom2020-148","soal":"Daerah X memiliki 250 penduduk dengan sakit jantung dari total jumlah penduduk 5.000.000 jiwa. Berapakah angka proporsi kejadiannya jika dinyatakan dalam bentuk desimal rasio total?","opsi":["0,00005 (atau 0,005%)","33,35","0,25","1,25","5,00"],"jawabanBenar":0,"pembahasan":"Proporsi atau insidens rate dihitung dengan membagi 250 dengan 5.000.000, menghasilkan 0,00005 (0,005%)[cite: 1].","pembahasanPilihan":["Proporsi atau insidens rate dihitung dengan membagi 250 dengan 5.000.000, menghasilkan 0,00005 (0,005%)[cite: 1].","33,35 adalah angka acak yang tidak sesuai.","0,25 adalah hasil yang keliru.","1,25 adalah hasil yang keliru.","5,00 adalah hasil yang keliru."],"version":1},{"id":"kedkom2020-149","soal":"Anak laki-laki 14 tahun dibawa ke IGD akibat pendarahan hebat menabrak lampu merah dalam pengaruh alkohol. Ayahnya berkata anaknya pergi karena marah dilarang merayakan tahun baru. Manakah di bawah ini yang TIDAK termasuk ciri-ciri masalah sosial?","opsi":["Selalu dianggap sebagai berkah yang membahagiakan seluruh anggota masyarakat","Menimbulkan keresahan bagi sebagian besar warga","Bersumber dari kondisi penyimpangan perilaku sosial","Memerlukan penanganan kolektif bersama","Melanggar norma yang berlaku"],"jawabanBenar":0,"pembahasan":"Masalah sosial adalah kondisi yang dinilai merugikan dan meresahkan masyarakat, sehingga pernyataan bahwa masalah sosial selalu dianggap berkah membahagiakan adalah keliru[cite: 1].","pembahasanPilihan":["Masalah sosial adalah kondisi yang dinilai merugikan dan meresahkan masyarakat, sehingga pernyataan bahwa masalah sosial selalu dianggap berkah membahagiakan adalah keliru[cite: 1].","Meresahkan warga adalah ciri masalah sosial.","Bersumber dari perilaku menyimpang.","Memerlukan penanganan bersama.","Melanggar norma."],"version":1},{"id":"kedkom2020-150","soal":"Dalam manajemen penanggulangan bencana dan krisis kesehatan, setelah fase tanggap darurat selesai dan kondisi berangsur pulih, tahapan apakah yang menandai kembalinya aktivitas normal secara bertahap?","opsi":["Fase Transisi darurat menuju pemulihan (Recovery / pascakrisis)","Fase Hantaman bencana langsung (Impact)","Fase Siaga siaga darurat aktif","Fase Mitigasi struktural awal","Fase Evakuasi militer"],"jawabanBenar":0,"pembahasan":"Fase transisi darurat menuju pemulihan adalah masa ketika ancaman akut mereda dan masyarakat mulai menata kembali kehidupan sosial ekonomi serta kesehatannya[cite: 1].","pembahasanPilihan":["Fase transisi darurat menuju pemulihan adalah masa ketika ancaman akut mereda dan masyarakat mulai menata kembali kehidupan sosial ekonomi serta kesehatannya[cite: 1].","Impact adalah saat terjadinya hantaman bencana.","Siaga darurat saat ancaman aktif.","Mitigasi jauh sebelum bencana.","Evakuasi saat penyelamatan awal."],"version":1},{"id":"kedkom2020-151","soal":"Gangguan pertumbuhan dan perkembangan anak bisa dicegah bila penilaian dilakukan secara rutin sesuai jadwal yang direkomendasikan Kementerian Kesehatan RI. Bagaimanakah jadwal rekomendasi skrining perkembangan anak balita yang dianjurkan?","opsi":["Setiap 3 bulan sekali untuk anak usia 0-24 bulan, dan setiap 6 bulan sekali untuk anak usia 24-72 bulan","Hanya sekali seumur hidup saat masuk sekolah dasar","Setiap 10 tahun sekali","Hanya saat anak jatuh sakit parah di rumah sakit","Tidak perlu dilakukan skrining sama sekali"],"jawabanBenar":0,"pembahasan":"Berdasarkan pedoman SDIDTK Kementerian Kesehatan RI, skrining perkembangan anak dianjurkan dilakukan secara rutin setiap 3 bulan sekali hingga usia 2 tahun, dan setiap 6 bulan sekali dari usia 2 hingga 6 tahun[cite: 1].","pembahasanPilihan":["Berdasarkan pedoman SDIDTK Kementerian Kesehatan RI, skrining perkembangan anak dianjurkan dilakukan secara rutin setiap 3 bulan sekali hingga usia 2 tahun, dan setiap 6 bulan sekali dari usia 2 hingga 6 tahun[cite: 1].","Sekali seumur hidup terlambat mendeteksi gangguan tumbuh kembang.","10 tahun sekali tidak relevan untuk balita.","Skrining dilakukan rutin pada anak sehat di posyandu/puskesmas.","Skrining sangat penting untuk pencegahan dini."],"version":1},{"id":"kedkom2020-152","soal":"Dari 17 tujuan SDGs, terdapat 4 tujuan utama yang secara langsung terkait dengan bidang kesehatan dan kesejahteraan masyarakat. Tujuan manakah yang mencakup kelompok tersebut?","opsi":["Tujuan 2, 3, 5, dan 6 (Gizi, Kesehatan, Kesetaraan Gender, serta Air & Sanitasi)","Tujuan 7, 8, 9, dan 10","Tujuan 11, 12, 13, dan 14","Tujuan 13, 14, 15, dan 16","Tujuan 14, 15, 16, dan 17"],"jawabanBenar":0,"pembahasan":"Tujuan SDGs yang berkaitan langsung dengan kesehatan meliputi Tujuan 2 (gizi), Tujuan 3 (kesehatan), Tujuan 5 (gender), dan Tujuan 6 (air bersih dan sanitasi)[cite: 1].","pembahasanPilihan":["Tujuan SDGs yang berkaitan langsung dengan kesehatan meliputi Tujuan 2 (gizi), Tujuan 3 (kesehatan), Tujuan 5 (gender), dan Tujuan 6 (air bersih dan sanitasi)[cite: 1].","Tujuan 7-10 untuk energi dan ekonomi.","Tujuan 11-14 untuk kota dan iklim.","Tujuan 13-16 untuk iklim dan perdamaian.","Tujuan 14-17 untuk lautan dan kemitraan."],"version":1},{"id":"kedkom2020-153","soal":"Syariat Islam mengharuskan menciptakan kemaslahatan melalui penjagaan lima hal pokok (Hifzud Din, Hifzhun Nafs, Hifzhun Nasl, Hifzhun Aql, dan Hifzhul Mal). Eksistensi insan Islami sangat tergantung dari menjaga lima hal di atas yang dirumuskan oleh ulama sebagai apa?","opsi":["Tujuan Syariat Islam (Maqashid Syariah)","Hakikat hukum positif sekuler","Sumber hukum perdata barat","Hikmah administrasi modern","Makna kebudayaan material"],"jawabanBenar":0,"pembahasan":"Konsep penjagaan lima unsur pokok kehidupan manusia (agama, jiwa, keturunan, akal, dan harta) dirumuskan oleh para ulama sebagai Maqashid Syariah (Tujuan Syariat Islam)[cite: 1].","pembahasanPilihan":["Konsep penjagaan lima unsur pokok kehidupan manusia (agama, jiwa, keturunan, akal, dan harta) dirumuskan oleh para ulama sebagai Maqashid Syariah (Tujuan Syariat Islam)[cite: 1].","Bukan hukum positif sekuler.","Bukan hukum perdata barat.","Bukan administrasi modern.","Bukan kebudayaan material."],"version":1},{"id":"kedkom2020-154","soal":"Anak laki-laki kurang mendapat ASI, belum bisa berdiri, bisa duduk, hanya bisa bicara 'mama-papa', orang tua pemulung punya 5 anak. Instrumen skrining perkembangan apa yang direkomendasikan dan dapat dilakukan oleh keluarga serta guru PAUD?","opsi":["Kuesioner Pra Skrining Perkembangan (KPSP)","Skala psikometrik Bayley klinis mendalam","Tes Denver II psikolog lanjutan","Kuesioner psikiatrik PEDS","Skala autisme khusus"],"jawabanBenar":0,"pembahasan":"Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi yang praktis dan mudah diaplikasikan oleh keluarga serta guru PAUD[cite: 1].","pembahasanPilihan":["Kuesioner Pra Skrining Perkembangan (KPSP) adalah instrumen skrining resmi yang praktis dan mudah diaplikasikan oleh keluarga serta guru PAUD[cite: 1].","Bayley adalah alat asesmen psikologis klinis yang rumit.","Denver II memerlukan pelatihan khusus dan waktu lebih lama.","PEDS instrumen berbasis laporan orang tua, namun KPSP standar primer nasional.","Skala autisme khusus untuk autisme."],"version":1},{"id":"kedkom2020-155","soal":"Seorang pasien yang menjalani metode KB kalender datang ke bidan mengatakan tadi malam melakukan hubungan seksual pada masa subur. Pasien tidak mau hamil lagi karena anaknya sudah 3. Apakah tindakan kontrasepsi darurat atau penanganan yang paling tepat untuk menghindari kehamilan pada kasus tersebut?","opsi":["Memberikan kontrasepsi darurat (seperti pil kontrasepsi darurat atau pemasangan AKDR/IUD pasca senggama sesuai batas waktu medis)","Menganjurkan minum air putih hangat dicampur gula","Menyuruh pasien berolahraga lari maraton","Tidak melakukan apa pun dan membiarkan kehamilan terjadi","Memberikan vitamin C dosis rendah"],"jawabanBenar":0,"pembahasan":"Penanganan medis bagi wanita yang melakukan hubungan seksual tanpa perlindungan pada masa subur dan tidak ingin hamil adalah pemberian kontrasepsi darurat (emergency contraception) atau pemasangan AKDR segera[cite: 1].","pembahasanPilihan":["Penanganan medis bagi wanita yang melakukan hubungan seksual tanpa perlindungan pada masa subur dan tidak ingin hamil adalah pemberian kontrasepsi darurat (emergency contraception) atau pemasangan AKDR segera[cite: 1].","Air gula tidak mencegah kehamilan.","Lari maraton tidak mencegah fertilisasi.","Membiarkan bertentangan dengan keinginan pasien.","Vitamin C tidak memiliki efek kontrasepsi darurat."],"version":1},{"id":"kedkom2020-156","soal":"Bapak Tn. N berusia 68 tahun, iuran kepesertaan jaminan kesehatannya dibayarkan oleh pemerintah. Maka status kepesertaan BPJS Bapak Tn. N termasuk ke dalam golongan apa?","opsi":["Penerima Bantuan Iuran (PBI)","Pekerja Penerima Upah (PPU)","Pekerja Bukan Penerima Upah mandiri","Bukan Pekerja investor","Keluarga konglomerat"],"jawabanBenar":0,"pembahasan":"Peserta JKN dari kelompok masyarakat miskin dan tidak mampu yang iurannya dibiayai oleh pemerintah masuk dalam kategori Penerima Bantuan Iuran (PBI)[cite: 1].","pembahasanPilihan":["Peserta JKN dari kelompok masyarakat miskin dan tidak mampu yang iurannya dibiayai oleh pemerintah masuk dalam kategori Penerima Bantuan Iuran (PBI)[cite: 1].","PPU adalah pekerja formal berpenghasilan tetap.","PBPU adalah pekerja mandiri.","Bukan pekerja mencakup pensiunan.","Konglomerat bukan kategori jaminan sosial."],"version":1},{"id":"kedkom2020-157","soal":"Aspek sarana sanitasi dasar meliputi penyediaan air bersih, pengelolaan pembuangan air limbah, dan pembuangan sampah agar tercipta lingkungan yang sehat. Manakah komponen sarana penting lainnya yang juga menjadi bagian dari pilar sanitasi dasar masyarakat?","opsi":["Kepemilikan dan penggunaan jamban sehat keluarga (sarana buang air besar yang layak)","Kepemilikan mobil mewah pribadi","Ketersediaan bioskop hiburan modern","Keberadaan pusat perbelanjaan mal","Ketersediaan lapangan sepak bola rumput"],"jawabanBenar":0,"pembahasan":"Komponen utama pilar sanitasi dasar dalam kesehatan lingkungan mencakup sarana air bersih, pengelolaan limbah cair, pengelolaan sampah, serta kepemilikan dan penggunaan jamban sehat keluarga[cite: 1].","pembahasanPilihan":["Komponen utama pilar sanitasi dasar dalam kesehatan lingkungan mencakup sarana air bersih, pengelolaan limbah cair, pengelolaan sampah, serta kepemilikan dan penggunaan jamban sehat keluarga[cite: 1].","Mobil mewah tidak berkaitan dengan sanitasi dasar.","Bioskop adalah sarana hiburan.","Mal adalah pusat perbelanjaan.","Lapangan sepak bola adalah fasilitas olahraga."],"version":1}];
